INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('9679284b-8687-5fb3-830f-c00d1b961cf1', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 1, 1, 'A cyclist travels 4.8 km in 12 minutes. Calculate her average speed in m s⁻¹.', NULL, 1, 'numeric'::answer_type, '6.667', 'm s⁻¹', false, NULL, false, NULL, 'v = 4800 ÷ (12 × 60) = 6.7 m s⁻¹. Mark scheme (2 marks). C1: km to m and min to s. A1: v = 6.7 m s⁻¹.', 2, NULL, NULL),
('e31ac51c-41aa-57c0-8d11-a0c96d26b507', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 2, 2, 'Which equation defines average speed?', NULL, 1, 'multiple_choice'::answer_type, 'Average speed = total distance travelled ÷ total time taken', NULL, false, NULL, false, NULL, 'Speed is the rate of covering distance. Mark scheme (1 mark). B1: C (Average speed = total distance travelled ÷ total time taken).', 1, NULL, NULL),
('56bf4c42-1740-577b-90c8-c2a5c6740db5', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 3, 3, 'Convert a speed of 72 km h⁻¹ into m s⁻¹.', NULL, 1, 'numeric'::answer_type, '20', 'm s⁻¹', false, NULL, false, NULL, 'v = 72 × 1000 ÷ 3600 = 20 m s⁻¹. Mark scheme (2 marks). C1: × 1000 ÷ 3600. A1: v = 20 m s⁻¹.', 2, NULL, NULL),
('6d0cc004-1bcb-5501-9f7d-74bcee8324a8', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 4, 4, 'A sprinter runs 100 m in 10.4 s. Calculate the average speed.', NULL, 1, 'numeric'::answer_type, '9.615', 'm s⁻¹', false, NULL, false, NULL, 'v = 100 ÷ 10.4 = 9.62 m s⁻¹. Mark scheme (2 marks). C1: v = d/t. A1: v = 9.62 m s⁻¹.', 2, NULL, NULL),
('fa18335e-6517-5ad1-946b-17ddb0e909dd', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 5, 5, 'What is the SI unit of speed?', NULL, 1, 'multiple_choice'::answer_type, 'm s⁻¹', NULL, false, NULL, false, NULL, 'Metres per second, written m s⁻¹. Mark scheme (1 mark). B1: A (m s⁻¹).', 1, NULL, NULL),
('bc675977-46a2-5a2f-a654-2fd25df48fa1', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 6, 6, 'A snail crawls at 1.5 mm s⁻¹. How far does it crawl in 5.0 minutes, in metres?', NULL, 1, 'numeric'::answer_type, '0.45', 'm', false, NULL, false, NULL, 'd = 1.5 × 10⁻³ × 300 = 0.45 m. Mark scheme (2 marks). C1: mm to m, min to s. A1: d = 0.45 m.', 2, NULL, NULL),
('39d60fd0-cb7c-5e1d-88f7-0217a228191d', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 7, 7, 'Convert 15 m s⁻¹ into km h⁻¹.', NULL, 1, 'numeric'::answer_type, '54', 'km h⁻¹', false, NULL, false, NULL, 'v = 15 × 3600 ÷ 1000 = 54 km h⁻¹. Mark scheme (2 marks). C1: × 3.6. A1: v = 54 km h⁻¹.', 2, NULL, NULL),
('5a0e6895-f56c-5cf5-9f16-16abbe4e4c6a', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 8, 8, 'A car''s speedometer reads 50 km h⁻¹. What does this reading show?', NULL, 1, 'multiple_choice'::answer_type, 'The instantaneous speed', NULL, false, NULL, false, NULL, 'A speedometer shows the speed at that instant. Mark scheme (1 mark). B1: D (The instantaneous speed).', 1, NULL, NULL),
('0345a3e7-2498-5a2b-8ab3-05fe6cd3a675', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 9, 9, 'Light travels at 3.0 × 10⁸ m s⁻¹. How long does it take to travel 1.5 × 10¹¹ m from the Sun to the Earth?', NULL, 1, 'numeric'::answer_type, '500', 's', false, NULL, false, NULL, 't = 1.5 × 10¹¹ ÷ 3.0 × 10⁸ = 500 s. Mark scheme (2 marks). C1: t = d/v. A1: t = 500 s.', 2, NULL, NULL),
('0f85d796-eeab-51a5-a31a-981aae75581e', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 10, 10, 'A train travels at a steady 45 m s⁻¹ for 8.0 minutes. Calculate the distance covered, in km.', NULL, 1, 'numeric'::answer_type, '21.6 km', 'km', false, NULL, false, NULL, 'd = 45 × 480 = 21 600 m. In km: 21 600 ÷ 1000 = 21.6. Mark scheme (2 marks). C1: d = vt with t in s. A1: d = 21.6 km.', 2, NULL, NULL),
('f973cc03-6f48-5132-a753-335d34264d11', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 11, 11, 'Which quantity can be found from the distance a runner covers and the time taken?', NULL, 1, 'multiple_choice'::answer_type, 'Average speed', NULL, false, NULL, false, NULL, 'Average speed = distance ÷ time. Mark scheme (1 mark). B1: B (Average speed).', 1, NULL, NULL),
('2617e459-ed54-5913-91cc-59406658961d', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 12, 12, 'A walker covers 3.6 km in 1.0 hour. Calculate the average speed in m s⁻¹.', NULL, 1, 'numeric'::answer_type, '1', 'm s⁻¹', false, NULL, false, NULL, 'v = 3600 ÷ 3600 = 1.0 m s⁻¹. Mark scheme (1 mark). A1: v = 1.0 m s⁻¹.', 1, NULL, NULL),
('770a9144-e35f-5f89-a1ca-ad581fe998ff', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 13, 13, 'Sound travels at 340 m s⁻¹ in air. How far away is a lightning strike if the thunder arrives 4.5 s after the flash?', NULL, 1, 'numeric'::answer_type, '1530', 'm', false, NULL, false, NULL, 'd = 340 × 4.5 = 1530 m. Mark scheme (2 marks). C1: d = vt. A1: d = 1530 m.', 2, NULL, NULL),
('f7a23b91-9438-5b28-98a7-898e16f8e715', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 14, 14, 'Why is the average speed of a car on a journey usually less than its top speed?', NULL, 1, 'multiple_choice'::answer_type, 'It stops, slows down and speeds up during the journey', NULL, false, NULL, false, NULL, 'Average speed takes account of all the slow parts. Mark scheme (1 mark). B1: C (It stops, slows down and speeds up during the journey).', 1, NULL, NULL),
('16525ed1-5b05-5496-b9a0-69facc85efa4', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 15, 15, 'An athlete runs 400 m in 52 s. Calculate the average speed.', NULL, 1, 'numeric'::answer_type, '7.692', 'm s⁻¹', false, NULL, false, NULL, 'v = 400 ÷ 52 = 7.69 m s⁻¹. Mark scheme (2 marks). C1: v = d/t. A1: v = 7.69 m s⁻¹.', 2, NULL, NULL),
('68610a2e-adc7-59a7-b4e2-9cced98a749d', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 16, 16, 'A swimmer completes 50 m at an average speed of 1.6 m s⁻¹. Calculate the time taken.', NULL, 1, 'numeric'::answer_type, '31.25', 's', false, NULL, false, NULL, 't = 50 ÷ 1.6 = 31.3 s. Mark scheme (2 marks). C1: t = d/v. A1: t = 31.2 s.', 2, NULL, NULL),
('83597753-1dde-5a92-bf24-598833890d88', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 17, 17, 'A ball rolls 2.0 m in the first second and 1.5 m in the next second. What can you say about its speed?', NULL, 1, 'multiple_choice'::answer_type, 'It is slowing down', NULL, false, NULL, false, NULL, 'Less distance in each equal time means a falling speed. Mark scheme (1 mark). B1: A (It is slowing down).', 1, NULL, NULL),
('98b8b594-ecf8-5ab8-853e-3b9da09fe6c7', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 18, 18, 'A marathon of 42.2 km is run in 2 hours 5 minutes. Calculate the average speed in m s⁻¹.', NULL, 1, 'numeric'::answer_type, '5.627', 'm s⁻¹', false, NULL, false, NULL, 't = 2 × 3600 + 5 × 60 = 7500 s. v = 42 200 ÷ 7500 = 5.63 m s⁻¹. Mark scheme (2 marks). C1: units converted. A1: v = 5.63 m s⁻¹.', 2, NULL, NULL),
('cf9031f1-336b-50b7-95bf-ff55a714eac9', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 19, 19, 'Which of these speeds is the greatest?', NULL, 1, 'multiple_choice'::answer_type, '100 km h⁻¹', NULL, false, NULL, false, NULL, 'In m s⁻¹ they are 27.8, 25, 26.7 and 20. Mark scheme (1 mark). B1: D (100 km h⁻¹).', 1, NULL, NULL),
('943dff0c-4d18-5176-a392-f36994ceb205', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 20, 20, 'A car travels 30 km at 60 km h⁻¹ and then 30 km at 90 km h⁻¹. Calculate its average speed for the whole journey in km h⁻¹.', NULL, 2, 'numeric'::answer_type, '72', 'km h⁻¹', false, NULL, false, NULL, 'Times: 30 ÷ 60 = 0.500 h and 30 ÷ 90 = 0.333 h. Average speed = 60 ÷ (0.500 + 0.3333) = 72 km h⁻¹. Mark scheme (3 marks). C1: time of each stage. C1: total distance ÷ total time. A1: v = 72 km h⁻¹.', 3, NULL, NULL),
('3c51fbf2-7a3b-5f90-87a1-2b50e7c6cd9f', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 21, 21, 'A light gate records that a card of length 10.0 cm takes 0.040 s to pass through it. Calculate the speed of the trolley carrying the card.', NULL, 2, 'numeric'::answer_type, '2.5', 'm s⁻¹', false, NULL, false, NULL, 'v = 0.100 ÷ 0.040 = 2.5 m s⁻¹. Mark scheme (3 marks). C1: cm to m. C1: v = length ÷ time. A1: v = 2.5 m s⁻¹.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 190" role="img" aria-labelledby="fg56ea4b03-t fg56ea4b03-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg56ea4b03-t">Card and light gate</title><desc id="fg56ea4b03-d">A trolley carrying a 10.0 cm card passes through a light gate.</desc><line x1="20" y1="140" x2="400" y2="140" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30" y1="140" x2="22" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="70" y1="140" x2="62" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="110" y1="140" x2="102" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="150" y1="140" x2="142" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="190" y1="140" x2="182" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="230" y1="140" x2="222" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="270" y1="140" x2="262" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="310" y1="140" x2="302" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="350" y1="140" x2="342" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="390" y1="140" x2="382" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="40" y="112" width="70" height="22" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="54" cy="136" r="4" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="96" cy="136" r="4" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="68" y="82" width="14" height="30" rx="0" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="75" y="70" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">10.0 cm card</text><line x1="118" y1="123" x2="144.4" y2="123" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="150,123 142.7,126.4 142.7,119.6" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><path d="M236,136 L236,66 L268,66 L268,136" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="238" y1="95" x2="266" y2="95" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:3 2"/><text x="252" y="54" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">light gate</text></svg>', 'A trolley carrying a 10.0 cm card passes through a light gate.'),
('a6a2003b-5774-51e1-95b5-11b654802d44', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 22, 22, 'A runner covers the first 200 m of a race in 25 s and the next 200 m in 31 s. Calculate the average speed for the 400 m.', NULL, 2, 'numeric'::answer_type, '7.143', 'm s⁻¹', false, NULL, false, NULL, 'v = 400 ÷ (25 + 31) = 7.14 m s⁻¹. Mark scheme (3 marks). C1: total time. C1: total distance ÷ total time. A1: v = 7.14 m s⁻¹.', 3, NULL, NULL),
('ceea4a1e-e124-50b2-9fdb-9b6d9241d8f7', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 23, 23, 'Why is the average speed for a journey not the mean of the speeds in two equal-distance stages?', NULL, 2, 'multiple_choice'::answer_type, 'More time is spent at the lower speed, so the lower speed counts for more', NULL, false, NULL, false, NULL, 'Average speed = total distance ÷ total time. Mark scheme (3 marks). C1: unequal times. C1: weighting to lower speed. A1: D (More time is spent at the lower speed, so the lower speed counts for more).', 3, NULL, NULL),
('ab25f7f1-c4f2-5d74-a2b8-7220aeb638cf', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 24, 24, 'A ship sails at 18 knots, where 1 knot = 0.514 m s⁻¹. How far does it travel in 2.5 hours, in km?', NULL, 2, 'numeric'::answer_type, '83.27 km', 'km', false, NULL, false, NULL, 'v = 18 × 0.514 = 9.25 m s⁻¹. d = 9.252 × 9000 = 83 268 m. In km: 83 268 ÷ 1000 = 83.3. Mark scheme (3 marks). C1: knots to m s⁻¹. C1: d = vt. A1: d = 83.3 km.', 3, NULL, NULL),
('240879bc-ec17-5681-ae58-63c25ca02f98', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 25, 25, 'A radar pulse travels at 3.0 × 10⁸ m s⁻¹ to an aircraft and back in 2.0 × 10⁻⁴ s. Calculate the distance to the aircraft, in km.', NULL, 2, 'numeric'::answer_type, '30 km', 'km', false, NULL, false, NULL, 'd = 3.0 × 10⁸ × 2.0 × 10⁻⁴ ÷ 2 = 30 000 m. In km: 30 000 ÷ 1000 = 30. Mark scheme (3 marks). C1: there and back, so halve. C1: value. A1: d = 30 km.', 3, NULL, NULL),
('0bf7a03f-45b2-5f7d-b63a-f11f84a63738', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 26, 26, 'A bus completes a 12 km route in 40 minutes, including 10 minutes spent stopped. Calculate its average speed while moving, in km h⁻¹.', NULL, 2, 'numeric'::answer_type, '24', 'km h⁻¹', false, NULL, false, NULL, 'Moving time = 30 min = 0.50 h. v = 12 ÷ 0.50 = 24 km h⁻¹. Mark scheme (3 marks). C1: moving time. C1: v = d/t. A1: v = 24 km h⁻¹.', 3, NULL, NULL),
('48b5a1c7-90d7-52b7-864f-ac3e9b9d9aff', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 27, 27, 'How can the speed of a trolley be measured using one light gate?', NULL, 2, 'multiple_choice'::answer_type, 'Fix a card of known length to the trolley and divide its length by the time it blocks the beam', NULL, false, NULL, false, NULL, 'Speed = length of card ÷ interruption time. Mark scheme (3 marks). C1: card of known length. C1: speed = length/time. A1: B (Fix a card of known length to the trolley and divide its length by the time it blocks the beam).', 3, NULL, NULL),
('a4e93efe-363e-51eb-b4e0-9982c57e6ae5', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 28, 28, 'A car travelling at 31 m s⁻¹ passes a speed camera that photographs it twice, 0.50 s apart. How far apart are the car''s positions in the two photographs?', NULL, 2, 'numeric'::answer_type, '15.5', 'm', false, NULL, false, NULL, 'd = 31 × 0.50 = 15.5 m. Mark scheme (3 marks). C1: d = vt. C1: value. A1: d = 15.5 m.', 3, NULL, NULL),
('5d17f150-1e78-5fd9-9cea-5d05528635e1', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 29, 29, 'A jogger runs 3.0 km at 2.5 m s⁻¹ and walks the next 1.0 km at 1.25 m s⁻¹. Calculate the average speed for the 4.0 km.', NULL, 2, 'numeric'::answer_type, '2', 'm s⁻¹', false, NULL, false, NULL, 'Times: 3000 ÷ 2.5 = 1200 s and 1000 ÷ 1.25 = 800 s. v = 4000 ÷ (1200 + 800) = 2.0 m s⁻¹. Mark scheme (4 marks). C1: first time. C1: second time. C1: average. A1: v = 2.0 m s⁻¹.', 4, NULL, NULL),
('5326bd5b-a8f9-5c68-adca-c5c717fec4a2', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 30, 30, 'A ticker-timer makes 50 dots each second. Ten dot-spaces on a tape measure 12.0 cm. Calculate the average speed of the tape.', NULL, 2, 'numeric'::answer_type, '0.6', 'm s⁻¹', false, NULL, false, NULL, 'Time = 10 ÷ 50 = 0.20 s. v = 0.120 ÷ 0.20 = 0.60 m s⁻¹. Mark scheme (3 marks). C1: time for 10 spaces. C1: v = d/t. A1: v = 0.60 m s⁻¹.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 440 120" role="img" aria-labelledby="fg302fb915-t fg302fb915-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg302fb915-t">Ticker tape</title><desc id="fg302fb915-d">A ticker tape with eleven equally spaced dots; the ten spaces between the first and last dots measure 12.0 cm.</desc><rect x="24" y="30" width="392" height="32" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="34" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="71.2" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="108.4" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="145.6" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="182.8" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="220" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="257.2" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="294.4" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="331.6" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="368.8" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="406" cy="46" r="3" style="fill:currentColor;stroke:none"/><polygon points="34,80 40.3,77 40.3,83" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="38.9" y1="80" x2="401.1" y2="80" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="406,80 399.7,83 399.7,77" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="220" y="92" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">12.0 cm</text><line x1="34" y1="64" x2="34" y2="84" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><line x1="406" y1="64" x2="406" y2="84" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/></svg>', 'A ticker tape with eleven equally spaced dots; the ten spaces between the first and last dots measure 12.0 cm.'),
('412fcf8f-6b14-5898-8ab7-005aab4b6daa', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 31, 31, 'On a ticker tape, the spacing between dots increases along the tape. What does this show?', NULL, 2, 'multiple_choice'::answer_type, 'The object was speeding up', NULL, false, NULL, false, NULL, 'Equal time intervals with growing distances mean rising speed. Mark scheme (3 marks). C1: equal time between dots. C1: larger distance per interval. A1: C (The object was speeding up).', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 440 120" role="img" aria-labelledby="fgc05dc1f2-t fgc05dc1f2-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgc05dc1f2-t">Ticker tape</title><desc id="fgc05dc1f2-d">A ticker tape on which the spaces between successive dots get steadily larger along the tape.</desc><rect x="24" y="30" width="392" height="32" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="34" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="47.8" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="68.4" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="96" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="130.4" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="171.8" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="220" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="275.1" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="337.1" cy="46" r="3" style="fill:currentColor;stroke:none"/><circle cx="406" cy="46" r="3" style="fill:currentColor;stroke:none"/></svg>', 'A ticker tape on which the spaces between successive dots get steadily larger along the tape.'),
('6b16b34f-feba-5dcc-8d7c-b390684c17e0', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 32, 32, 'A satellite orbits the Earth once every 90 minutes in a circle of radius 6.7 × 10⁶ m. Calculate its speed, in units of 10³ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '7.796', '10³ m s⁻¹', false, NULL, false, NULL, 'v = 2π × 6.7 × 10⁶ ÷ 5400 = 7800 m s⁻¹. Mark scheme (3 marks). C1: circumference. C1: period in s. A1: v = 7.80 × 10³ m s⁻¹.', 3, NULL, NULL),
('828202fc-70d2-5dbd-8af8-0103f49b180b', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 33, 33, 'An aircraft cruises at 250 m s⁻¹. How long does it take to fly 5400 km, in hours?', NULL, 2, 'numeric'::answer_type, '6', 'h', false, NULL, false, NULL, 't = 5.4 × 10⁶ ÷ 250 = 21 600 s. In hours: 21 600 ÷ 3600 = 6.0. Mark scheme (3 marks). C1: km to m. C1: s to h. A1: t = 6.0 h.', 3, NULL, NULL),
('a365441a-14a2-54f9-9191-41508f9a4161', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 34, 34, 'Two runners start together. One runs at 6.0 m s⁻¹ and the other at 5.0 m s⁻¹. How far apart are they after 2.0 minutes?', NULL, 2, 'numeric'::answer_type, '120', 'm', false, NULL, false, NULL, 'Separation = (6.0 − 5.0) × 120 = 120 m. Mark scheme (3 marks). C1: time in s. C1: difference in distances. A1: Δd = 120 m.', 3, NULL, NULL),
('a36d662d-223e-5fbb-87c3-ad560024b46b', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 35, 35, 'A student times a toy car over 1.0 m with a stopwatch, getting 0.8 s. Why is this speed measurement unreliable?', NULL, 2, 'multiple_choice'::answer_type, 'Reaction time (about 0.2 s) is a large fraction of the time measured', NULL, false, NULL, false, NULL, 'Use a longer distance or electronic timing. Mark scheme (3 marks). C1: reaction time. C1: compared with 0.8 s. A1: A (Reaction time (about 0.2 s) is a large fraction of the time measured).', 3, NULL, NULL),
('d2334f26-0097-51e5-b956-7ccc653d39d9', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 36, 36, 'A car travels 150 km in 2 hours 30 minutes. Calculate its average speed in m s⁻¹.', NULL, 2, 'numeric'::answer_type, '16.67', 'm s⁻¹', false, NULL, false, NULL, 't = 2.5 × 3600 = 9000 s. v = 150 000 ÷ 9000 = 16.7 m s⁻¹. Mark scheme (3 marks). C1: time in s. C1: v. A1: v = 16.7 m s⁻¹.', 3, NULL, NULL),
('2c182ed3-1e4c-5291-b941-fa573d2aca54', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 37, 37, 'An echo from a cliff is heard 1.8 s after a shout. Sound travels at 330 m s⁻¹. Calculate the distance to the cliff.', NULL, 2, 'numeric'::answer_type, '297', 'm', false, NULL, false, NULL, 'd = 330 × 1.8 ÷ 2 = 297 m. Mark scheme (3 marks). C1: there and back. C1: d = vt/2. A1: d = 297 m.', 3, NULL, NULL),
('fd4c21f6-904c-5336-af2e-d8822966595d', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 38, 38, 'A lorry travels at 22 m s⁻¹. A car behind it travels at 28 m s⁻¹. How long does the car take to close a 90 m gap?', NULL, 2, 'numeric'::answer_type, '15', 's', false, NULL, false, NULL, 'Closing speed = 28 − 22 = 6 m s⁻¹. t = 90 ÷ 6 = 15 s. Mark scheme (3 marks). C1: relative speed. C1: t = d/v. A1: t = 15 s.', 3, NULL, NULL),
('4a93a245-958d-535b-90b9-cca4080100a9', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 39, 39, 'A car is driven at a steady 27 m s⁻¹ for 15 minutes. How far does it travel, in km?', NULL, 2, 'numeric'::answer_type, '24.3 km', 'km', false, NULL, false, NULL, 'd = 27 × 900 = 24 300 m. In km: 24 300 ÷ 1000 = 24.3. Mark scheme (3 marks). C1: minutes to seconds. C1: d = vt. A1: d = 24.3 km.', 3, NULL, NULL),
('79fcf75d-c17a-5452-a843-4e5c7c8224ff', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 40, 40, 'A runner''s stride is 1.8 m long and she takes 3.0 strides each second. Calculate her speed.', NULL, 2, 'numeric'::answer_type, '5.4', 'm s⁻¹', false, NULL, false, NULL, 'v = 1.8 × 3.0 = 5.4 m s⁻¹. Mark scheme (3 marks). C1: distance per second. C1: value. A1: v = 5.4 m s⁻¹.', 3, NULL, NULL),
('b647323b-40e2-53c9-95f5-f7a8225dbcce', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 41, 41, 'A cyclist rides 12 km uphill at 15 km h⁻¹ and returns down the same road at 40 km h⁻¹. (a) Calculate the time for each stage. (b) Calculate the average speed for the round trip, in km h⁻¹.', NULL, 3, 'numeric'::answer_type, '21.82', 'km h⁻¹', false, NULL, false, NULL, '(a) 12 ÷ 15 = 0.80 h; 12 ÷ 40 = 0.30 h. (b) v = 24 ÷ (0.80 + 0.30) = 21.8 km h⁻¹. Mark scheme (5 marks). C1: uphill time. C1: downhill time. M1: total distance ÷ total time. C1: value. A1: v = 21.8 km h⁻¹.', 5, NULL, NULL),
('c4de8cd0-98d0-5694-a557-d037303fb988', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 42, 42, 'A car must average 80 km h⁻¹ over a 160 km trip. It covers the first 80 km at 64 km h⁻¹. (a) Calculate the time allowed for the whole trip. (b) Calculate the time used so far. (c) Calculate the average speed needed for the rest, in km h⁻¹.', NULL, 3, 'numeric'::answer_type, '106.7', 'km h⁻¹', false, NULL, false, NULL, '(a) 160 ÷ 80 = 2.0 h. (b) 80 ÷ 64 = 1.25 h. (c) v = 80 ÷ (2.0 − 1.25) = 107 km h⁻¹. Mark scheme (6 marks). C1: total time. C1: time so far. M1: remaining time. C1: remaining distance ÷ time. C1: value. A1: v = 107 km h⁻¹.', 6, NULL, NULL),
('d76c754b-2d56-58a5-bd46-c5893d5da2a1', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 43, 43, 'In a relay, four runners each run 100 m. Their times are 10.8 s, 10.2 s, 10.5 s and 10.1 s. (a) Calculate the team''s average speed. (b) By how much does the fastest runner''s average speed exceed the team''s?', NULL, 3, 'numeric'::answer_type, '0.2856', 'm s⁻¹', false, NULL, false, NULL, '(a) v = 400 ÷ (10.8 + 10.2 + 10.5 + 10.1) = 9.615 m s⁻¹. (b) 100 ÷ 10.1 = 9.901 m s⁻¹; difference = 9.901 − 9.615 = 0.29 m s⁻¹. Mark scheme (5 marks). C1: total time. C1: team speed. M1: fastest speed. C1: difference. A1: Δv = 0.29 m s⁻¹.', 5, NULL, NULL),
('be604d9f-fb53-5041-b201-616d1fb0792f', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 44, 44, 'A sound pulse from a ship takes 0.24 s to return from a shoal of fish and 0.80 s to return from the sea bed. Sound travels at 1500 m s⁻¹ in sea water. (a) Calculate the depth of the shoal. (b) Calculate the depth of the sea bed. (c) Calculate the distance between the shoal and the sea bed.', NULL, 3, 'numeric'::answer_type, '420', 'm', false, NULL, false, NULL, '(a) 1500 × 0.24 ÷ 2 = 180 m. (b) 1500 × 0.80 ÷ 2 = 600 m. (c) 600 − 180 = 420 m. Mark scheme (6 marks). M1: halve the echo time. C1: shoal depth. C1: sea-bed depth. C1: subtraction. C1: value. A1: Δd = 420 m.', 6, NULL, NULL),
('d2e6e278-c7b1-537b-9eac-770589137a9e', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 45, 45, 'A train passes through a 1.2 km tunnel at 30 m s⁻¹. The train is 300 m long. (a) Explain why the train travels further than 1.2 km between the front entering and the rear leaving. (b) Calculate the time from the front entering to the rear leaving.', NULL, 3, 'numeric'::answer_type, '50', 's', false, NULL, false, NULL, '(a) The rear must also clear the tunnel, so the train travels 1200 + 300 = 1500 m. (b) t = 1500 ÷ 30 = 50 s. Mark scheme (5 marks). B1: tunnel + train length. C1: 1500 m. M1: t = d/v. C1: value. A1: t = 50 s.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 460 190" role="img" aria-labelledby="fg58b9a5b3-t fg58b9a5b3-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg58b9a5b3-t">Train and tunnel</title><desc id="fg58b9a5b3-d">A 300 m train approaching a 1.2 km tunnel; the rear must clear the tunnel exit.</desc><line x1="46" y1="62" x2="414" y2="62" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 4"/><circle cx="46" cy="62" r="5" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="46" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">rear</text><circle cx="96.2" cy="62" r="5" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="96.2" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">front</text><circle cx="213.3" cy="62" r="5" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="213.3" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">entrance</text><circle cx="414" cy="62" r="5" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="414" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">exit</text><polygon points="46,116 52.3,113 52.3,119" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="50.9" y1="116" x2="91.3" y2="116" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="96.2,116 89.8,119 89.8,113" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="71.1" y="128" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">300 m</text><line x1="46" y1="74" x2="46" y2="120" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><line x1="96.2" y1="74" x2="96.2" y2="120" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><polygon points="213.3,146 219.6,143 219.6,149" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="218.2" y1="146" x2="409.1" y2="146" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="414,146 407.7,149 407.7,143" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="313.6" y="158" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.2 km</text><line x1="213.3" y1="74" x2="213.3" y2="150" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><line x1="414" y1="74" x2="414" y2="150" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:2 3"/><text x="452" y="182" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">not to scale</text></svg>', 'A 300 m train approaching a 1.2 km tunnel; the rear must clear the tunnel exit.'),
('d4953886-2b7d-5b62-b63a-ae526f8c8a2c', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 46, 46, 'Two cars start 5.0 km apart and drive towards each other at 20 m s⁻¹ and 30 m s⁻¹. (a) Calculate their closing speed. (b) Calculate how far the slower car has travelled when they meet.', NULL, 3, 'numeric'::answer_type, '2000', 'm', false, NULL, false, NULL, '(a) 20 + 30 = 50 m s⁻¹. (b) t = 5000 ÷ 50 = 100 s; d = 20 × 100 = 2000 m. Mark scheme (5 marks). C1: closing speed. M1: time to meet. C1: t = 100 s. C1: distance. A1: d = 2000 m.', 5, NULL, NULL),
('f6730b3e-f866-5aeb-9eae-e6def91b1031', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 47, 47, 'A runner completes 25 laps of a 400 m track in 28 minutes 20 seconds. (a) Calculate the total distance. (b) Calculate the average speed. (c) Calculate the average time per lap.', NULL, 3, 'numeric'::answer_type, '68', 's', false, NULL, false, NULL, '(a) 25 × 400 = 10 000 m. (b) t = 28 × 60 + 20 = 1700 s; v = 10 000 ÷ 1700 = 5.88 m s⁻¹. (c) 1700 ÷ 25 = 68 s. Mark scheme (6 marks). C1: distance. C1: time in s. C1: average speed. M1: time per lap. C1: value. A1: t = 68 s.', 6, NULL, NULL),
('51ca209e-c743-5795-9953-0ab5d15a5e64', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 48, 48, 'A delivery van averages 50 km h⁻¹ in town for 18 km and 100 km h⁻¹ on a motorway for 75 km. (a) Calculate the time for each part. (b) Calculate the average speed for the whole trip, in km h⁻¹.', NULL, 3, 'numeric'::answer_type, '83.78', 'km h⁻¹', false, NULL, false, NULL, '(a) 18 ÷ 50 = 0.36 h; 75 ÷ 100 = 0.75 h. (b) v = 93 ÷ (0.36 + 0.75) = 83.8 km h⁻¹. Mark scheme (5 marks). C1: town time. C1: motorway time. M1: total ÷ total. C1: value. A1: v = 83.8 km h⁻¹.', 5, NULL, NULL),
('f81c0787-472f-5578-85ae-02a433698e9e', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 49, 49, 'Light from the Moon takes 1.28 s to reach the Earth. A laser pulse is sent to a reflector on the Moon and back. (a) Calculate the Earth–Moon distance. (b) Calculate the time for the round trip of the pulse. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '2.56', 's', false, NULL, false, NULL, '(a) d = 3.00 × 10⁸ × 1.28 = 3.84 × 10⁸ m. (b) t = 2 × 1.28 = 2.56 s. Mark scheme (5 marks). C1: d = ct. C1: value. M1: there and back. C1: value. A1: t = 2.56 s.', 5, NULL, NULL),
('22f47111-82ea-57e0-9353-1242395faf10', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 50, 50, 'A car accelerates so that it covers 4.0 m, 12 m and 20 m in three successive seconds. (a) Calculate the average speed in each second. (b) Calculate the average speed over the three seconds. (c) State whether its speed was constant.', NULL, 3, 'numeric'::answer_type, '12', 'm s⁻¹', false, NULL, false, NULL, '(a) 4.0, 12 and 20 m s⁻¹. (b) v = (4.0 + 12 + 20) ÷ 3 = 12 m s⁻¹. (c) No, it increased. Mark scheme (6 marks). C1: each average speed. C1: total distance. M1: ÷ total time. C1: value. B1: not constant. A1: v = 12 m s⁻¹.', 6, NULL, NULL),
('a27f35d0-ce0d-5f5b-973b-bb44e94a4bac', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 51, 51, 'A pulse of ultrasound travels through 4.5 cm of tissue and back in 60 µs. (a) Calculate the total distance travelled. (b) Calculate the speed of ultrasound in the tissue.', NULL, 3, 'numeric'::answer_type, '1500', 'm s⁻¹', false, NULL, false, NULL, '(a) 2 × 4.5 = 9.0 cm. (b) v = 0.090 ÷ 60 × 10⁻⁶ = 1500 m s⁻¹. Mark scheme (5 marks). C1: twice the depth. C1: cm to m. M1: v = d/t with µs. C1: value. A1: v = 1500 m s⁻¹.', 5, NULL, NULL),
('e41b7266-48ce-5456-8cb1-40ca905d74a9', '4653a171-76f9-4b44-bc1d-19802787195f', 'ffbe7a62-e4c5-4cb6-8a20-6f0177f86d30', 'a-level', '1.1', '9702 coursebook 1.1 · Speed', 52, 52, 'A passenger walks at 1.2 m s⁻¹ along a moving walkway that moves at 0.40 m s⁻¹ in the same direction. The walkway is 60 m long. (a) Calculate her speed relative to the ground. (b) Calculate the time to travel the length of the walkway.', NULL, 3, 'numeric'::answer_type, '37.5', 's', false, NULL, false, NULL, '(a) v = 1.2 + 0.40 = 1.6 m s⁻¹. (b) t = 60 ÷ 1.6 = 37.5 s. Mark scheme (5 marks). M1: add speeds. C1: 1.6 m s⁻¹. M1: t = d/v. C1: value. A1: t = 37.5 s.', 5, NULL, NULL)
