('26efd9ab-d788-5c53-a6f8-e3d3ec866457', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 1, 1, 'What is the difference between distance and displacement?', NULL, 1, 'multiple_choice'::answer_type, 'Displacement is distance in a stated direction; distance has no direction', NULL, false, NULL, false, NULL, 'Displacement is a vector quantity. Mark scheme (1 mark). B1: C (Displacement is distance in a stated direction; distance has no direction).', 1, NULL, NULL),
('0d81e151-3b46-5a14-bef8-b26a29883841', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 2, 2, 'Which of these is a vector quantity?', NULL, 1, 'multiple_choice'::answer_type, 'Displacement', NULL, false, NULL, false, NULL, 'A vector has both magnitude and direction. Mark scheme (1 mark). B1: A (Displacement).', 1, NULL, NULL),
('5d890634-7b28-5764-80bf-1bf0f5a8adcb', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 3, 3, 'Which of these is a scalar quantity?', NULL, 1, 'multiple_choice'::answer_type, 'Distance', NULL, false, NULL, false, NULL, 'A scalar has magnitude only. Mark scheme (1 mark). B1: D (Distance).', 1, NULL, NULL),
('1a5510c7-e532-5b75-a501-b1a936db1f0b', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 4, 4, 'A boy walks 40 m north and then 15 m south. Calculate his displacement from the start.', NULL, 1, 'numeric'::answer_type, '25', 'm', false, NULL, false, NULL, 'Displacement = 40 − 15 = 25 m north. Mark scheme (2 marks). C1: subtract opposite directions. A1: s = 25 m.', 2, NULL, NULL),
('6d0233c7-baa5-56fa-8975-aaaa667770e2', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 5, 5, 'A boy walks 40 m north and then 15 m south. Calculate the distance he walks.', NULL, 1, 'numeric'::answer_type, '55', 'm', false, NULL, false, NULL, 'Distance = 40 + 15 = 55 m. Mark scheme (2 marks). C1: add distances. A1: d = 55 m.', 2, NULL, NULL),
('d896693d-9c31-5d8d-80f1-4c082707b7ad', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 6, 6, 'A hiker walks 3.0 km east and then 4.0 km north. Calculate the magnitude of her displacement.', NULL, 1, 'numeric'::answer_type, '5 km', 'km', false, NULL, false, NULL, 's = √(3.0² + 4.0²) = 5.0 km. Mark scheme (2 marks). C1: Pythagoras. A1: s = 5.0 km.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fge0f2601c-t fge0f2601c-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fge0f2601c-t">Two legs of a walk</title><desc id="fge0f2601c-d">A walk of 3.0 km east followed by 4.0 km north, with the resultant displacement dashed from start to finish.</desc><line x1="109.5" y1="234" x2="244.2" y2="234" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="250.5,234 242.3,237.8 242.3,230.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="180" y="248" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">3.0 km</text><line x1="250.5" y1="234" x2="250.5" y2="52.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="250.5,46 254.3,54.2 246.7,54.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="264.5" y="144" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">4.0 km</text><line x1="109.5" y1="234" x2="246.7" y2="51" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="250.5,46 248.6,54.8 242.6,50.2" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="191.2" y="148.4" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="109.5" cy="234" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'A walk of 3.0 km east followed by 4.0 km north, with the resultant displacement dashed from start to finish.'),
('093241ac-c0de-53af-a73d-bc15c081f280', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 7, 7, 'A runner completes one full lap of a 400 m track. What is her displacement at the finish?', NULL, 1, 'multiple_choice'::answer_type, 'Zero', NULL, false, NULL, false, NULL, 'She ends where she started. Mark scheme (1 mark). B1: B (Zero).', 1, NULL, NULL),
('c111e707-d3f0-5985-af89-0a507a957437', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 8, 8, 'A runner completes 2.5 laps of a 400 m circular track. Calculate the distance run.', NULL, 1, 'numeric'::answer_type, '1000', 'm', false, NULL, false, NULL, 'd = 2.5 × 400 = 1000 m. Mark scheme (2 marks). C1: laps × length. A1: d = 1000 m.', 2, NULL, NULL),
('e8cbc1fc-9e32-5d5d-91ba-7e71fc00f6ff', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 9, 9, 'What two things must be stated to describe a displacement fully?', NULL, 1, 'multiple_choice'::answer_type, 'A magnitude and a direction', NULL, false, NULL, false, NULL, 'For example 25 m due north. Mark scheme (1 mark). B1: C (A magnitude and a direction).', 1, NULL, NULL),
('b25525d1-c816-529e-b4b4-c4464ef02d5d', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 10, 10, 'A lift rises 24 m from the ground floor and then descends 9.0 m. Calculate its displacement from the ground floor.', NULL, 1, 'numeric'::answer_type, '15', 'm', false, NULL, false, NULL, 's = 24 − 9.0 = 15 m upwards. Mark scheme (2 marks). C1: up − down. A1: s = 15 m.', 2, NULL, NULL),
('49f00658-0264-51f2-9d97-8b6b83f36aff', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 11, 11, 'Which statement about a vector quantity is correct?', NULL, 1, 'multiple_choice'::answer_type, 'It is fully described only when its direction is given', NULL, false, NULL, false, NULL, 'Direction is part of the quantity. Mark scheme (1 mark). B1: A (It is fully described only when its direction is given).', 1, NULL, NULL),
('ff31864f-b54c-564a-98bc-19364f011f50', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 12, 12, 'An ant walks along three sides of a square of side 20 cm. Calculate the distance it walks, in cm.', NULL, 1, 'numeric'::answer_type, '60 cm', 'cm', false, NULL, false, NULL, 'Three sides: d = 3 × 20 = 60 cm. Mark scheme (1 mark). A1: d = 60 cm.', 1, NULL, NULL),
('60fd0b28-6d99-51ec-93da-55659a3d180c', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 13, 13, 'An ant walks along three sides of a square of side 20 cm. Calculate the magnitude of its displacement, in cm.', NULL, 1, 'numeric'::answer_type, '20 cm', 'cm', false, NULL, false, NULL, 'Three sides leave it one side from the start: s = 20 × 1 = 20 cm. Mark scheme (2 marks). C1: ends one side from start. A1: s = 20 cm.', 2, NULL, NULL),
('63ab5dcc-1441-5ba6-aea3-650e73038531', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 14, 14, 'Can the magnitude of a displacement ever be greater than the distance travelled?', NULL, 1, 'multiple_choice'::answer_type, 'No, it can be equal or smaller but never greater', NULL, false, NULL, false, NULL, 'The straight line is the shortest path. Mark scheme (1 mark). B1: D (No, it can be equal or smaller but never greater).', 1, NULL, NULL),
('1bdc6d93-3597-5d9f-a934-722b67901c16', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 15, 15, 'A ball is thrown 6.0 m straight up and falls back into the thrower''s hand. Calculate the distance it travels.', NULL, 1, 'numeric'::answer_type, '12', 'm', false, NULL, false, NULL, 'd = 6.0 + 6.0 = 12 m. Mark scheme (2 marks). C1: up + down. A1: d = 12 m.', 2, NULL, NULL),
