('196825bb-17bb-51e2-a9dd-a78192d88a81', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 17, 17, 'A car drives 8.0 km west then 6.0 km south. Calculate the magnitude of its displacement.', NULL, 1, 'numeric'::answer_type, '10 km', 'km', false, NULL, false, NULL, 's = √(8.0² + 6.0²) = 10 km. Mark scheme (2 marks). C1: Pythagoras. A1: s = 10 km.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg0b2c54c5-t fg0b2c54c5-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg0b2c54c5-t">Car journey</title><desc id="fg0b2c54c5-d">A car drives 8.0 km west and then 6.0 km south; the resultant displacement is dashed.</desc><line x1="296.4" y1="52.7" x2="69.9" y2="52.7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="63.6,52.7 71.7,48.9 71.7,56.5" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="180" y="38.7" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">8.0 km</text><line x1="63.6" y1="52.7" x2="63.6" y2="221" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="63.6,227.3 59.8,219.2 67.4,219.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="49.6" y="144" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">6.0 km</text><line x1="296.4" y1="52.7" x2="68.6" y2="223.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="63.6,227.3 67.8,219.4 72.4,225.5" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="171.6" y="128.8" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="296.4" cy="52.7" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'A car drives 8.0 km west and then 6.0 km south; the resultant displacement is dashed.'),
('b89a1565-0a6b-574c-868a-41fc6f160cd0', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 18, 18, 'A cat climbs 2.5 m up a tree and then jumps 1.0 m down onto a branch. Calculate its displacement from the ground.', NULL, 1, 'numeric'::answer_type, '1.5', 'm', false, NULL, false, NULL, 's = 2.5 − 1.0 = 1.5 m upwards. Mark scheme (2 marks). C1: up − down. A1: s = 1.5 m.', 2, NULL, NULL),
('710c3238-a384-54d6-9f93-2533fc71fc7f', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 19, 19, 'Which statement describes a displacement rather than a distance?', NULL, 1, 'multiple_choice'::answer_type, '"The ship is 12 km north-west of the port"', NULL, false, NULL, false, NULL, 'Only the first gives a direction from a reference point. Mark scheme (1 mark). B1: C ("The ship is 12 km north-west of the port").', 1, NULL, NULL),
('735106ca-c4ee-52b9-b46d-7084bb179c44', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 20, 20, 'A cyclist rides half way round a circular track of radius 50 m. Calculate (a) the distance and (b) the magnitude of the displacement. Give the answer to (b).', NULL, 2, 'numeric'::answer_type, '100', 'm', false, NULL, false, NULL, '(a) d = π × 50 = 157 m. (b) s = 2 × 50 = 100 m (the diameter). Mark scheme (3 marks). C1: half circumference. C1: diameter. A1: s = 100 m.', 3, NULL, NULL),
('44635c62-fdbe-56cf-b56a-6a38b6532765', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 21, 21, 'A cyclist rides half way round a circular track of radius 50 m. Calculate the distance ridden.', NULL, 2, 'numeric'::answer_type, '157.1', 'm', false, NULL, false, NULL, 'Half the circumference: d = π × 50 = 157 m. Mark scheme (3 marks). C1: half of 2πr. C1: value. A1: d = 157 m.', 3, NULL, NULL),
