yle="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="174.6" y="127.1" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="63.6" cy="188.5" r="3.4" style="fill:currentColor;stroke:none"/><line x1="63.6" y1="188.5" x2="63.6" y2="144.5" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:3 3"/><path d="M63.6,158.5 A30,30 0 0,1 91.3,177" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="86.9" y="153.6" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">θ</text><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'A walk of 5.0 km north then 12 km east, with the resultant dashed and the angle θ east of north marked at the start.'),
