('7aa39c86-2458-5358-b5c6-01fd97ae9fb4', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 24, 24, 'A dog runs around a field and returns to its owner. Which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'Its displacement is zero but the distance it ran is not', NULL, false, NULL, false, NULL, 'Returning to the start gives zero displacement. Mark scheme (3 marks). C1: displacement zero. C1: distance non-zero. A1: C (Its displacement is zero but the distance it ran is not).', 3, NULL, NULL),
('2011343d-f9c4-5581-a133-7375433365e0', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 25, 25, 'A robot moves 6.0 m east, 3.0 m north and then 2.0 m west. Calculate the magnitude of its final displacement.', NULL, 2, 'numeric'::answer_type, '5', 'm', false, NULL, false, NULL, 'Net east = 6.0 − 2.0 = 4.0 m; north = 3.0 m. s = √(4.0² + 3.0²) = 5.0 m. Mark scheme (3 marks). C1: net east component. C1: Pythagoras. A1: s = 5.0 m.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg14bd4841-t fg14bd4841-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg14bd4841-t">Robot path</title><desc id="fg14bd4841-d">A robot moves 6.0 m east, 3.0 m north and then 2.0 m west; the resultant displacement is dashed.</desc><line x1="56.8" y1="201.6" x2="296.9" y2="201.6" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="303.2,201.6 295,205.4 295,197.8" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="180" y="215.6" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">6.0 m</text><line x1="303.2" y1="201.6" x2="303.2" y2="84.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="303.2,78.4 307,86.6 299.4,86.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="317.2" y="144" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">3.0 m</text><line x1="303.2" y1="78.4" x2="227.4" y2="78.4" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="221.1,78.4 229.2,74.6 229.2,82.2" style="fill:currentColor;stroke:none"/><text x="262.1" y="64.4" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.0 m</text><line x1="56.8" y1="201.6" x2="216" y2="82.2" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="221.1,78.4 216.8,86.4 212.2,80.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="147.3" y="151.2" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="56.8" cy="201.6" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'A robot moves 6.0 m east, 3.0 m north and then 2.0 m west; the resultant displacement is dashed.'),
('e0362ed9-70a8-5531-8538-bf3c19f87e8e', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 26, 26, 'A pendulum bob swings from one end of its swing to the other, a straight-line separation of 12 cm, along an arc of length 13 cm. Calculate (arc distance) ÷ (displacement).', NULL, 2, 'numeric'::answer_type, '1.083', NULL, false, NULL, false, NULL, 'Ratio = 13 ÷ 12 = 1.08. Mark scheme (3 marks). C1: distance is the arc. C1: displacement is the chord. A1: ratio = 1.08.', 3, NULL, NULL),
('d4bb50f8-047c-5b98-895f-306622d0a023', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 27, 27, 'A ship sails 30 km due south and then 40 km due west. Calculate the bearing of its final position from the start.', NULL, 2, 'numeric'::answer_type, '233.1', '°', false, NULL, false, NULL, 'Angle west of south = tan⁻¹(40 ÷ 30) = 53.1°. Bearing = 180 + 53.1 = 233°. Mark scheme (3 marks). C1: angle west of south. C1: bearing. A1: bearing = 233°.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg18d0e318-t fg18d0e318-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg18d0e318-t">Ship voyage</title><desc id="fg18d0e318-d">A ship sails 30 km south and then 40 km west; the resultant is dashed from the start.</desc><line x1="300" y1="50" x2="300" y2="223.7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="300,230 296.2,221.9 303.8,221.9" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="314" y="144" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">30 km</text><line x1="300" y1="230" x2="66.3" y2="230" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="60,230 68.1,226.2 68.1,233.8" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="180" y="244" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">40 km</text><line x1="300" y1="50" x2="65" y2="226.2" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="60,230 64.2,222.1 68.8,228.2" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="188.4" y="151.2" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="300" cy="50" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'A ship sails 30 km south and then 40 km west; the resultant is dashed from the start.'),
('21228fd8-d3bb-5acd-a53e-2ae5e4ff662d', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 28, 28, 'Why is it wrong to add a 3 km displacement north and a 4 km displacement east to get 7 km?', NULL, 2, 'multiple_choice'::answer_type, 'They are vectors in different directions, so they must be added with a vector diagram (giving 5 km)', NULL, false, NULL, false, NULL, 'Vectors at right angles add by Pythagoras. Mark scheme (3 marks). C1: vectors. C1: direction matters. A1: A (They are vectors in different directions, so they must be added with a vector diagram (giving 5 km)).', 3, NULL, NULL),
('2bbea8e5-6276-559a-a0e9-8ecb0ce19414', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 29, 29, 'A swimmer swims 4 lengths of a 25 m pool, starting and finishing at the same end. Calculate the distance swum and state the displacement. Give the distance.', NULL, 2, 'numeric'::answer_type, '100', 'm', false, NULL, false, NULL, 'd = 4 × 25 = 100 m; the displacement is zero because she finishes at the start. Mark scheme (3 marks). C1: distance. C1: zero displacement. A1: d = 100 m.', 3, NULL, NULL),
('534ccd17-f2e7-5d5e-953e-e8cbdaf290ea', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 30, 30, 'A climber rises 300 m vertically while moving 400 m horizontally. Calculate the magnitude of her displacement.', NULL, 2, 'numeric'::answer_type, '500', 'm', false, NULL, false, NULL, 's = √(300² + 400²) = 500 m. Mark scheme (3 marks). C1: right-angled components. C1: Pythagoras. A1: s = 500 m.', 3, NULL, NULL),
('da9f99d9-410f-54bc-94e1-ae10ff52df37', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 31, 31, 'A car goes round three-quarters of a circular roundabout of radius 20 m. Calculate the magnitude of its displacement.', NULL, 2, 'numeric'::answer_type, '28.28', 'm', false, NULL, false, NULL, 'Start and end are 90° apart on the circle: s = √(20² + 20²) = 28.3 m. Mark scheme (4 marks). M1: positions 90° apart. C1: chord. C1: value. A1: s = 28.3 m.', 4, NULL, NULL),
('c8ba3bcc-858e-5765-a707-a5ad26d2c27b', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 32, 32, 'A car goes round three-quarters of a circular roundabout of radius 20 m. Calculate the distance travelled.', NULL, 2, 'numeric'::answer_type, '94.25', 'm', false, NULL, false, NULL, 'd = 0.75 × 2π × 20 = 94.2 m. Mark scheme (3 marks). C1: fraction of circumference. C1: value. A1: d = 94.2 m.', 3, NULL, NULL),
('806a9f93-060f-5605-8e8a-8731c5b2fa5e', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 33, 33, 'Which pair contains one scalar and one vector?', NULL, 2, 'multiple_choice'::answer_type, 'Distance and displacement', NULL, false, NULL, false, NULL, 'Distance is scalar; displacement is vector. Mark scheme (3 marks). C1: distance scalar. C1: displacement vector. A1: D (Distance and displacement).', 3, NULL, NULL),
('e73b64d6-27a6-5cb5-9f82-55c0d3a5aa8b', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 34, 34, 'A drone flies 120 m north, rises 50 m, then flies 120 m south. Calculate the magnitude of its displacement.', NULL, 2, 'numeric'::answer_type, '50', 'm', false, NULL, false, NULL, 'North and south cancel: s = 120 − 120 + 50 = 50 m upwards. Mark scheme (3 marks). C1: horizontal parts cancel. C1: vertical remains. A1: s = 50 m.', 3, NULL, NULL),
('4990f0a7-035a-50cd-9edc-007eb1aa3a5b', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 35, 35, 'A drone flies 120 m north, rises 50 m, then flies 120 m south. Calculate the distance it flies.', NULL, 2, 'numeric'::answer_type, '290', 'm', false, NULL, false, NULL, 'd = 120 + 50 + 120 = 290 m. Mark scheme (3 marks). C1: add all lengths. C1: value. A1: d = 290 m.', 3, NULL, NULL),
('9f2be628-7ecd-5528-9fbb-f3d35d066b78', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 36, 36, 'A student says "the car''s displacement is 40 km". What is missing?', NULL, 2, 'multiple_choice'::answer_type, 'The direction, e.g. 40 km north-east', NULL, false, NULL, false, NULL, 'A vector needs a direction. Mark scheme (3 marks). C1: displacement is a vector. C1: direction required. A1: B (The direction, e.g. 40 km north-east).', 3, NULL, NULL),
('bfd56624-46ef-50c0-81fc-150b1f2f26b2', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 37, 37, 'A walker goes 600 m on a bearing of 090° and then 800 m on a bearing of 180°. Calculate the magnitude of the displacement.', NULL, 2, 'numeric'::answer_type, '1000', 'm', false, NULL, false, NULL, 's = √(600² + 800²) = 1000 m. Mark scheme (3 marks). C1: perpendicular legs. C1: Pythagoras. A1: s = 1000 m.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg53077841-t fg53077841-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg53077841-t">Walk on bearings</title><desc id="fg53077841-d">A walk of 600 m on a bearing of 090° (east) and then 800 m on a bearing of 180° (south); the resultant is dashed.</desc><line x1="109.5" y1="46" x2="244.2" y2="46" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="250.5,46 242.3,49.8 242.3,42.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="180" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">600 m</text><line x1="250.5" y1="46" x2="250.5" y2="227.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="250.5,234 246.7,225.8 254.3,225.8" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="264.5" y="144" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">800 m</text><line x1="109.5" y1="46" x2="246.7" y2="229" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="250.5,234 242.6,229.8 248.6,225.2"