('47725e6a-4795-5fdc-8706-14f4dbccf98e', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 38, 38, 'A rugby player runs 18 m forward and 7.5 m sideways. Calculate the angle of his displacement from the forward direction.', NULL, 2, 'numeric'::answer_type, '22.62', '°', false, NULL, false, NULL, 'θ = tan⁻¹(7.5 ÷ 18) = 22.6°. Mark scheme (3 marks). C1: tan θ = side/forward. C1: value. A1: θ = 22.6°.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg744838ae-t fg744838ae-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg744838ae-t">Rugby run</title><desc id="fg744838ae-d">A run of 18 m forward and 7.5 m sideways, with the resultant displacement dashed and its angle θ to the forward direction marked.</desc><line x1="140.8" y1="234" x2="140.8" y2="52.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="140.8,46 144.6,54.2 137,54.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="126.8" y="144" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">18 m forward</text><line x1="140.8" y1="46" x2="212.9" y2="46" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="219.2,46 211,49.8 211,42.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="180" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">7.5 m</text><line x1="140.8" y1="234" x2="216.7" y2="51.8" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="219.2,46 219.5,55 212.5,52.1" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="167.1" y="134.6" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="140.8" cy="234" r="3.4" style="fill:currentColor;stroke:none"/><line x1="140.8" y1="234" x2="140.8" y2="190" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:3 3"/><path d="M140.8,204 A30,30 0 0,1 152.4,206.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="149.1" y="192.8" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">θ</text></svg>', 'A run of 18 m forward and 7.5 m sideways, with the resultant displacement dashed and its angle θ to the forward direction marked.'),
('c06d8673-0b07-5623-bb12-4c8b2ca1e87f', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 39, 39, 'A golf ball moves 120 m north with one shot and 50 m east with the next. Calculate the magnitude of its displacement.', NULL, 2, 'numeric'::answer_type, '130', 'm', false, NULL, false, NULL, 's = √(120² + 50²) = 130 m. Mark scheme (3 marks). C1: perpendicular. C1: Pythagoras. A1: s = 130 m.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fgb2da7d85-t fgb2da7d85-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgb2da7d85-t">Two golf shots</title><desc id="fgb2da7d85-d">A golf ball moves 120 m north and then 50 m east; the resultant displacement is dashed.</desc><line x1="140.8" y1="234" x2="140.8" y2="52.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="140.8,46 144.6,54.2 137,54.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="126.8" y="144" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">120 m</text><line x1="140.8" y1="46" x2="212.9" y2="46" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="219.2,46 211,49.8 211,42.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="180" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">50 m</text><line x1="140.8" y1="234" x2="216.7" y2="51.8" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="219.2,46 219.5,55 212.5,52.1" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="167.1" y="134.6" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="140.8" cy="234" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'A golf ball moves 120 m north and then 50 m east; the resultant displacement is dashed.'),
('02430fda-c9bb-5ffe-bf8f-b615a27a6bd7', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 40, 40, 'Starting from a jetty, a kayaker paddles 2.0 km towards the north-east (045°) and then 2.0 km towards the south-east (135°). How far is she from the jetty?', NULL, 2, 'numeric'::answer_type, '2.828 km', 'km', false, NULL, false, NULL, 'The legs are at 90° to each other: s = √(2.0² + 2.0²) = 2.83 km. Mark scheme (3 marks). C1: legs perpendicular. C1: Pythagoras. A1: s = 2.83 km.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg17b4a6b2-t fg17b4a6b2-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg17b4a6b2-t">Kayak route</title><desc id="fg17b4a6b2-d">A kayaker paddles 2.0 km north-east (045°) and then 2.0 km south-east (135°); the resultant is dashed.</desc><line x1="63.6" y1="198.2" x2="175.5" y2="86.2" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="180,81.8 176.9,90.2 171.5,84.9" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="111.9" y="130.1" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">2.0 km</text><line x1="180" y1="81.8" x2="292" y2="193.8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="296.4,198.2 288,195.1 293.4,189.8" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="248.1" y="130.1" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">2.0 km</text><line x1="63.6" y1="198.2" x2="290.1" y2="198.2" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="296.4,198.2 288.3,202 288.3,194.4" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="180" y="184.2" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="63.6" cy="198.2" r="3.4" style="fill:currentColor;stroke:none"/><text x="55.6" y="212.2" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">jetty</text><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'A kayaker paddles 2.0 km north-east (045°) and then 2.0 km south-east (135°); the resultant is dashed.'),
('927c914e-6517-50b2-a70a-404b76063f4c', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 41, 41, 'A yacht sails 8.0 km north, then 6.0 km east, then 2.0 km south. (a) Find the net north and east displacements. (b) Calculate the magnitude of the resultant displacement.', NULL, 3, 'numeric'::answer_type, '8.485 km', 'km', false, NULL, false, NULL, '(a) North: 8.0 − 2.0 = 6.0 km; east: 6.0 km. (b) s = √(6.0² + 6.0²) = 8.49 km. Mark scheme (5 marks). C1: north component. C1: east component. M1: Pythagoras. C1: value. A1: s = 8.49 km.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg93f550cb-t fg93f550cb-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg93f550cb-t">Yacht course</title><desc id="fg93f550cb-d">A yacht sails 8.0 km north, 6.0 km east and then 2.0 km south; the resultant displacement is dashed.</desc><line x1="109.5" y1="234" x2="109.5" y2="52.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="109.5,46 113.3,54.2 105.7,54.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="95.5" y="144" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">8.0 km</text><line x1="109.5" y1="46" x2="244.2" y2="46" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="250.5,46 242.3,49.8 242.3,42.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="180" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">6.0 km</text><line x1="250.5" y1="46" x2="250.5" y2="86.7" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="250.5,93 246.7,84.8 254.3,84.8" style="fill:currentColor;stroke:none"/><text x="264.5" y="73.5" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">2.0 km</text><line x1="109.5" y1="234" x2="246" y2="97.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="250.5,93 247.4,101.5 242,96.1" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="170.1" y="153.6" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="109.5" cy="234" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'A yacht sails 8.0 km north, 6.0 km east and then 2.0 km south; the resultant displacement is dashed.'),
('98fce39b-6174-589b-867b-2ba2262ad9f1', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 42, 42, 'A yacht sails 8.0 km north, then 6.0 km east, then 2.0 km south. (a) Find the resultant displacement. (b) Find its bearing from the start. Give the bearing.', NULL, 3, 'numeric'::answer_type, '45', '°', false, NULL, false, NULL, '(a) 6.0 km north and 6.0 km east, so s = 8.49 km. (b) tan θ = 6.0 ÷ 6.0, θ = tan⁻¹(6.0 ÷ 6.0) = 45°, a bearing of 045°. Mark scheme (6 marks). C1: components. C1: magnitude. M1: tan θ = east/north. C1: angle. C1: bearing. A1: bearing = 45°.', 6, NULL, NULL),
('331f832c-3597-5aaa-b107-686ba0fbeaa4', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 43, 43, 'A child runs once round a circular path of diameter 30 m, then a further quarter lap. (a) Calculate the distance run. (b) Calculate the magnitude of the displacement.', NULL, 3, 'numeric'::answer_type, '21.21', 'm', false, NULL, false, NULL, '(a) d = 1.25 × π × 30 = 118 m. (b) A quarter lap from the start: s = √(15² + 15²) = 21.2 m. Mark scheme (5 marks). C1: circumference. C1: distance. M1: chord for 90°. C1: value. A1: s = 21.2 m.', 5, NULL, NULL),
('9ffc7495-1c7b-5715-811c-e96e28689fe2', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 44, 44, 'A hiker walks 5.0 km on a bearing of 060°, then 5.0 km on a bearing of 150°. (a) Find the east and north components of each leg. (b) Calculate the magnitude of the total displacement.', NULL, 3, 'numeric'::answer_type, '7.071 km', 'km', false, NULL, false, NULL, '(a) Leg 1: east 5.0 sin 60° = 4.33, north 5.0 cos 60° = 2.50. Leg 2: east 5.0 sin 150° = 2.50, north 5.0 cos 150° = −4.33. (b) s = √((4.33 + 2.50)² + (2.50 − 4.33)²) = 7.07 km. Mark scheme (6 marks). C1: leg 1 components. C1: leg 2 components. M1: add components. C1: Pythagoras. C1: value. A1: s = 7.07 km.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fgc5b88806-t fgc5b88806-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgc5b88806-t">Two bearings</title><desc id="fgc5b88806-d">A walk of 5.0 km on a bearing of 060° followed by 5.0 km on a bearing of 150°; the resultant is dashed.</desc><line x1="63.6" y1="151.4" x2="205.7" y2="69.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="211.2,66.2 206,73.6 202.2,67" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="130.4" y="96.7" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">5.0 km</text><line x1="211.2" y1="66.2" x2="293.3" y2="208.4" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="296.4,213.8 289.1,208.7 295.7,204.9" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="265.9" y="133" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">5.0 km</text><line x1="63.6" y1="151.4" x2="290.4" y2="212.2" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="296.4,213.8 287.6,215.4 289.5,208" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="183.6" y="169.1" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="63.6" cy="151.4" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'A walk of 5.0 km on a bearing of 060° followed by 5.0 km on a bearing of 150°; the resultant is dashed.'),
('c000dffe-4e6a-565c-b61c-6f76f6e946ea', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 45, 45, 'An insect crawls from one corner of a 3.0 cm cube to the opposite corner along three edges. (a) Calculate the distance crawled. (b) Calculate the magnitude of its displacement, in cm.', NULL, 3, 'numeric'::answer_type, '5.196 cm', 'cm', false, NULL, false, NULL, '(a) d = 3 × 3.0 = 9.0 cm. (b) s = √(3.0² + 3.0² + 3.0²) = 5.20 cm. Mark scheme (5 marks). C1: distance. M1: three perpendicular components. C1: Pythagoras in 3D. C1: value. A1: s = 5.20 cm.', 5, NULL, NULL),
('75dabb73-6de7-5a06-83a3-147e5f680ff0', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 46, 46, 'A ball rolls 4.0 m east, bounces off a wall, rolls 1.5 m west and stops. It took 3.0 s. (a) Calculate the distance. (b) Calculate the displacement. (c) Calculate (average speed) ÷ (magnitude of average velocity).', NULL, 3, 'numeric'::answer_type, '2.2', NULL, false, NULL, false, NULL, '(a) d = 4.0 + 1.5 = 5.5 m. (b) s = 4.0 − 1.5 = 2.5 m east. (c) Ratio = (5.5 ÷ 3.0) ÷ (2.5 ÷ 3.0) = 2.2. Mark scheme (6 marks). C1: distance. C1: displacement. M1: speed and velocity. C1: ratio. C1: value. A1: ratio = 2.2.', 6, NULL, NULL),
('802295df-8ccf-5d48-aa0a-4896d3c801a5', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 47, 47, 'A plane flies 300 km due east and then 400 km on a bearing of 030°. (a) Calculate the total east and north displacements. (b) Calculate the magnitude of the resultant.', NULL, 3, 'numeric'::answer_type, '608.3 km', 'km', false, NULL, false, NULL, '(a) East = 300 + 400 sin 30° = 500 km; north = 400 cos 30° = 346.4 km. (b) s = √(500² + 346.4²) = 608 km. Mark scheme (5 marks). C1: east. C1: north. M1: Pythagoras. C1: value. A1: s = 608 km.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg521562c4-t fg521562c4-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg521562c4-t">Flight path</title><desc id="fg521562c4-d">A plane flies 300 km east and then 400 km on a bearing of 030°; the resultant displacement is dashed.</desc><line x1="66.7" y1="218.5" x2="196.4" y2="218.5" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="202.7,218.5 194.5,222.3 194.5,214.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="134.7" y="232.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">300 km</text><line x1="202.7" y1="218.5" x2="290.2" y2="66.9" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="293.3,61.5 292.5,70.5 285.9,66.7" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="260.1" y="147" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">400 km</text><line x1="66.7" y1="218.5" x2="288.1" y2="65.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="293.3,61.5 288.8,69.3 284.4,63" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="188" y="151.5" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="66.7" cy="218.5" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'A plane flies 300 km east and then 400 km on a bearing of 030°; the resultant displacement is dashed.'),
('3677a09a-74b6-5362-97c3-2aba12bc557e', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 48, 48, 'A diver jumps up 0.80 m from a board 3.0 m above the water and then falls into the water. (a) Calculate the distance travelled until she reaches the water. (b) Calculate her displacement at the water surface from the board.', NULL, 3, 'numeric'::answer_type, '3', 'm', false, NULL, false, NULL, '(a) d = 0.80 + 0.80 + 3.0 = 4.6 m. (b) Up 0.80 m, down 0.80 m and down 3.0 m: s = 0.80 − 0.80 + 3.0 = 3.0 m downwards. Mark scheme (5 marks). C1: up and back down. C1: total distance. M1: start to finish. C1: value. A1: s = 3.0 m.', 5, NULL, NULL),
('663f58a9-02e4-5711-bf23-0e804dcd6403', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 49, 49, 'A city is laid out in square blocks of side 150 m. A taxi drives 4 blocks east, 3 blocks north and then 1 block west. (a) Calculate the distance driven. (b) Calculate the magnitude of the displacement. (c) Calculate its angle north of east.', NULL, 3, 'numeric'::answer_type, '45', '°', false, NULL, false, NULL, '(a) d = 8 × 150 = 1200 m. (b) Net 3 blocks east and 3 north: s = √(450² + 450²) = 636 m. (c) θ = tan⁻¹(450 ÷ 450) = 45°. Mark scheme (6 marks). C1: distance. C1: components. C1: magnitude. M1: tan θ. C1: value. A1: θ = 45°.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg7629dffa-t fg7629dffa-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg7629dffa-t">Taxi route</title><desc id="fg7629dffa-d">A taxi drives 4 blocks east, 3 blocks north and 1 block west on a grid of 150 m blocks; the resultant is dashed.</desc><line x1="73.5" y1="219.9" x2="280.2" y2="219.9" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="286.5,219.9 278.3,223.7 278.3,216.1" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="180" y="233.9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">4 blocks</text><line x1="286.5" y1="219.9" x2="286.5" y2="66.4" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="286.5,60.1 290.3,68.3 282.7,68.3" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="300.5" y="144" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">3 blocks</text><line x1="286.5" y1="60.1" x2="239.5" y2="60.1" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="233.2,60.1 241.4,56.3 241.4,63.9" style="fill:currentColor;stroke:none"/><text x="259.9" y="46.1" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1 block</text><line x1="73.5" y1="219.9" x2="228.8" y2="64.6" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="233.2,60.1 230.2,68.6 224.8,63.2" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="163.3" y="149.9" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="73.5" cy="219.9" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'A taxi drives 4 blocks east, 3 blocks north and 1 block west on a grid of 150 m blocks; the resultant is dashed.'),
('4f5a25b1-8aab-5b05-9f06-9c1b1aec3fd7', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 50, 50, 'A satellite moves through one-sixth of a circular orbit of radius 7000 km. (a) Calculate the distance travelled along the orbit. (b) Calculate the magnitude of its displacement.', NULL, 3, 'numeric'::answer_type, '7000 km', 'km', false, NULL, false, NULL, '(a) d = 2π × 7000 ÷ 6 = 7330 km. (b) The chord for 60° equals the radius: s = 7000 × 1 = 7000 km. Mark scheme (5 marks). C1: arc length. M1: chord for 60°. C1: equilateral triangle. C1: value. A1: s = 7000 km.', 5, NULL, NULL),
('969c4f22-4d24-58b6-b9e5-100b1b00afe8', '4653a171-76f9-4b44-bc1d-19802787195f', 'cbfde8f1-1390-4f8a-b259-ff4ad9ad516e', 'a-level', '1.2', '9702 coursebook 1.2 · Distance and displacement, scalar and vector', 51, 51, 'A sailor goes 10 km north, 10 km east, 10 km south and then 4.0 km west. (a) Calculate the distance sailed. (b) Calculate the magnitude of the displacement.', NULL, 3, 'numeric'::answer_type, '6 km', 'km', false, NULL, false, NULL, '(a) d = 10 + 10 + 10 + 4.0 = 34 km. (b) North and south cancel; east: s = 10 − 4.0 = 6.0 km east. Mark scheme (5 marks). C1: distance. M1: north and south cancel. C1: east − west. C1: value. A1: s = 6.0 km.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fgdf02a9fb-t fgdf02a9fb-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgdf02a9fb-t">Four legs</title><desc id="fgdf02a9fb-d">A sailor goes 10 km north, 10 km east, 10 km south and 4.0 km west; the resultant displacement is dashed.</desc><line x1="86" y1="234" x2="86" y2="52.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="86,46 89.8,54.2 82.2,54.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="72" y="144" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">10 km</text><line x1="86" y1="46" x2="267.7" y2="46" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="274,46 265.8,49.8 265.8,42.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="180" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">10 km</text><line x1="274" y1="46" x2="274" y2="227.7" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="274,234 270.2,225.8 277.8,225.8" style="fill:currentColor;stroke:none"/><text x="288" y="144" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">10 km</text><line x1="274" y1="234" x2="205.1" y2="234" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="198.8,234 207,230.2 207,237.8" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="236.4" y="248" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">4.0 km</text><line x1="86" y1="234" x2="192.5" y2="234" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="198.8,234 190.6,237.8 190.6,230.2" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="142.4" y="220" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="86" cy="234" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'A sailor goes 10 km north, 10 km east, 10 km south and 4.0 km west; the resultant displacement is dashed.')
