INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('be51632d-06e3-5d0e-a901-5c0f3dfaa5bc', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 1, 1, 'How is the velocity of an object defined?', NULL, 1, 'multiple_choice'::answer_type, 'The rate of change of displacement', NULL, false, NULL, false, NULL, 'Velocity = displacement ÷ time, a vector. Mark scheme (1 mark). B1: C (The rate of change of displacement).', 1, NULL, NULL),
('dc623846-c177-5c5b-8013-0548e973b730', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 2, 2, 'Which quantity is a vector?', NULL, 1, 'multiple_choice'::answer_type, 'Velocity', NULL, false, NULL, false, NULL, 'Velocity has a direction. Mark scheme (1 mark). B1: A (Velocity).', 1, NULL, NULL),
('0abd033c-f9d1-5441-aaf0-a7c7566e28cb', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 3, 3, 'A car moves 360 m due north in 24 s. Calculate its average velocity.', NULL, 1, 'numeric'::answer_type, '15', 'm s⁻¹', false, NULL, false, NULL, 'v = 360 ÷ 24 = 15 m s⁻¹ north. Mark scheme (2 marks). C1: v = s/t. A1: v = 15 m s⁻¹.', 2, NULL, NULL),
('8d2010cc-7fb2-5624-a9e5-5050ed1b8eef', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 4, 4, 'A car goes round a bend at a constant 20 m s⁻¹. What is changing?', NULL, 1, 'multiple_choice'::answer_type, 'Its velocity, because its direction changes', NULL, false, NULL, false, NULL, 'Velocity includes direction. Mark scheme (1 mark). B1: D (Its velocity, because its direction changes).', 1, NULL, NULL),
('f2b24a1a-f258-5edb-bcb6-3046999fc179', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 5, 5, 'A runner completes a 400 m lap in 80 s. Calculate her average speed.', NULL, 1, 'numeric'::answer_type, '5', 'm s⁻¹', false, NULL, false, NULL, 'v = 400 ÷ 80 = 5.0 m s⁻¹. Mark scheme (2 marks). C1: distance ÷ time. A1: speed = 5.0 m s⁻¹.', 2, NULL, NULL),
('ce179c51-a323-55ae-8b11-5784bf73c32e', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 6, 6, 'A runner completes a 400 m lap in 80 s, finishing where she started. What is her average velocity?', NULL, 1, 'multiple_choice'::answer_type, 'Zero', NULL, false, NULL, false, NULL, 'Zero displacement means zero average velocity. Mark scheme (1 mark). B1: B (Zero).', 1, NULL, NULL),
('55dd9cae-f5b2-5849-b24c-33ee6bdd23ae', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 7, 7, 'A lift moves 30 m downwards in 12 s. Calculate its average velocity, taking upwards as positive.', NULL, 1, 'numeric'::answer_type, '-2.5', 'm s⁻¹', false, NULL, true, NULL, 'v = −30 ÷ 12 = −2.5 m s⁻¹. Mark scheme (2 marks). C1: sign shows direction. A1: v = −2.5 m s⁻¹.', 2, NULL, NULL),
('b2dd26a1-58c7-5f5f-991c-94af4cc723ca', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 8, 8, 'Two cars travel at 25 m s⁻¹, one north and one south. Which statement is correct?', NULL, 1, 'multiple_choice'::answer_type, 'They have the same speed but different velocities', NULL, false, NULL, false, NULL, 'Velocity includes direction. Mark scheme (1 mark). B1: C (They have the same speed but different velocities).', 1, NULL, NULL),
('89faa30d-034d-5180-9cd7-b87e9a85bc85', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 9, 9, 'An aircraft flies 900 km due west in 1.5 h. Calculate its average velocity in km h⁻¹.', NULL, 1, 'numeric'::answer_type, '600', 'km h⁻¹', false, NULL, false, NULL, 'v = 900 ÷ 1.5 = 600 km h⁻¹ west. Mark scheme (2 marks). C1: v = s/t. A1: v = 600 km h⁻¹.', 2, NULL, NULL),
('060a5f6c-359a-5138-b61a-46b43c6a49aa', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 10, 10, 'What is the SI unit of velocity?', NULL, 1, 'multiple_choice'::answer_type, 'm s⁻¹', NULL, false, NULL, false, NULL, 'The same unit as speed. Mark scheme (1 mark). B1: A (m s⁻¹).', 1, NULL, NULL),
('aec9acec-dc88-5d08-aa9c-fe5744e5d363', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 11, 11, 'A ball moves at a constant velocity of 4.0 m s⁻¹ east. Calculate its displacement after 6.0 s.', NULL, 1, 'numeric'::answer_type, '24', 'm', false, NULL, false, NULL, 's = 4.0 × 6.0 = 24 m east. Mark scheme (2 marks). C1: s = vt. A1: s = 24 m.', 2, NULL, NULL),
('23658301-6200-5fa2-9712-fba46088f3ee', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 12, 12, 'Can an object have a constant speed but a changing velocity?', NULL, 1, 'multiple_choice'::answer_type, 'Yes, if it moves in a circle', NULL, false, NULL, false, NULL, 'Direction changes on a curved path. Mark scheme (1 mark). B1: D (Yes, if it moves in a circle).', 1, NULL, NULL),
('82add8cb-03f0-53c1-97df-0bb6537089a5', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 13, 13, 'A tortoise moves 1.2 m east in 20 s. Calculate its average velocity.', NULL, 1, 'numeric'::answer_type, '0.06', 'm s⁻¹', false, NULL, false, NULL, 'v = 1.2 ÷ 20 = 0.060 m s⁻¹ east. Mark scheme (1 mark). A1: v = 0.060 m s⁻¹.', 1, NULL, NULL),
('477d8f15-45da-5170-ba17-144dc25adce9', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 14, 14, 'Velocity can be negative. What does a negative velocity show?', NULL, 1, 'multiple_choice'::answer_type, 'Motion in the direction chosen as negative', NULL, false, NULL, false, NULL, 'The sign gives the direction. Mark scheme (1 mark). B1: B (Motion in the direction chosen as negative).', 1, NULL, NULL),
('acbf2418-34d7-59e1-b5f2-1fd61a46bde3', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 15, 15, 'A cyclist rides 2.0 km east in 400 s. Calculate her average velocity.', NULL, 1, 'numeric'::answer_type, '5', 'm s⁻¹', false, NULL, false, NULL, 'v = 2000 ÷ 400 = 5.0 m s⁻¹ east. Mark scheme (2 marks). C1: km to m. A1: v = 5.0 m s⁻¹.', 2, NULL, NULL),
('39f99851-4d06-55ab-b8bc-61ffef16083c', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 16, 16, 'A car''s velocity is "20 m s⁻¹ north-east". What is its speed?', NULL, 1, 'multiple_choice'::answer_type, '20 m s⁻¹', NULL, false, NULL, false, NULL, 'Speed is the magnitude of velocity. Mark scheme (1 mark). B1: C (20 m s⁻¹).', 1, NULL, NULL),
('87dabb6e-556f-5628-babb-588f02a22105', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 17, 17, 'A train travels 54 km due south in 30 minutes. Calculate its average velocity in m s⁻¹.', NULL, 1, 'numeric'::answer_type, '30', 'm s⁻¹', false, NULL, false, NULL, 'v = 54 000 ÷ 1800 = 30 m s⁻¹ south. Mark scheme (2 marks). C1: units to m and s. A1: v = 30 m s⁻¹.', 2, NULL, NULL),
('ee383fb5-01be-5c3c-a93d-bceab4eeb0e5', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 18, 18, 'A swimmer crosses a 50 m pool straight across in 40 s. Calculate her average velocity.', NULL, 1, 'numeric'::answer_type, '1.25', 'm s⁻¹', false, NULL, false, NULL, 'v = 50 ÷ 40 = 1.25 m s⁻¹ across the pool. Mark scheme (2 marks). C1: v = s/t. A1: v = 1.25 m s⁻¹.', 2, NULL, NULL),
('e876be56-a97e-549a-bed4-ac2ab16e58cb', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 19, 19, 'A car moves with constant velocity. What must be true?', NULL, 1, 'multiple_choice'::answer_type, 'Both its speed and its direction are constant', NULL, false, NULL, false, NULL, 'Constant velocity means no change in magnitude or direction. Mark scheme (1 mark). B1: D (Both its speed and its direction are constant).', 1, NULL, NULL),
('01ef0214-24b8-566f-977e-7bad71637f73', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 20, 20, 'A ship''s velocity is 8.0 m s⁻¹ due west. How long does it take to move 2.4 km west?', NULL, 1, 'numeric'::answer_type, '300', 's', false, NULL, false, NULL, 't = 2400 ÷ 8.0 = 300 s. Mark scheme (2 marks). C1: t = s/v. A1: t = 300 s.', 2, NULL, NULL),
('8e728edd-9a12-5ee7-897e-29162d2d2d20', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 21, 21, 'A walker goes 400 m east in 300 s and then 300 m north in 200 s. Calculate her average speed.', NULL, 2, 'numeric'::answer_type, '1.4', 'm s⁻¹', false, NULL, false, NULL, 'Speed = (400 + 300) ÷ (300 + 200) = 1.4 m s⁻¹. Mark scheme (3 marks). C1: total distance. C1: total time. A1: speed = 1.4 m s⁻¹.', 3, NULL, NULL),
('09bc8fbf-575f-5796-9352-7ad223a45c89', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 22, 22, 'A walker goes 400 m east in 300 s and then 300 m north in 200 s. Calculate the magnitude of her average velocity.', NULL, 2, 'numeric'::answer_type, '1', 'm s⁻¹', false, NULL, false, NULL, 's = √(400² + 300²) = 500 m; v = 500 ÷ 500 = 1.0 m s⁻¹. Mark scheme (3 marks). C1: displacement. C1: ÷ total time. A1: v = 1.0 m s⁻¹.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fgbb61a5c1-t fgbb61a5c1-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgbb61a5c1-t">Walk east then north</title><desc id="fgbb61a5c1-d">A walk of 400 m east (300 s) then 300 m north (200 s); the resultant displacement is dashed.</desc><line x1="60" y1="230" x2="293.7" y2="230" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="300,230 291.9,233.8 291.9,226.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="180" y="244" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">400 m</text><line x1="300" y1="230" x2="300" y2="56.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="300,50 303.8,58.1 296.2,58.1" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="314" y="144" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">300 m</text><line x1="60" y1="230" x2="295" y2="53.8" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="300,50 295.8,57.9 291.2,51.8" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="188.4" y="151.2" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="60" cy="230" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'A walk of 400 m east (300 s) then 300 m north (200 s); the resultant displacement is dashed.'),
('05ec4c01-53c3-588f-be16-881252cd5231', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 23, 23, 'Why is the average speed of a round trip never less than the magnitude of its average velocity?', NULL, 2, 'multiple_choice'::answer_type, 'Distance is always at least as large as the magnitude of displacement, and the times are the same', NULL, false, NULL, false, NULL, 'Both are divided by the same time. Mark scheme (3 marks). C1: distance ≥ |displacement|. C1: same time. A1: A (Distance is always at least as large as the magnitude of displacement, and the times are the same).', 3, NULL, NULL),
('6499f1da-8e2a-5dfa-a42b-4caf5bd2dcd1', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 24, 24, 'A ball is thrown up and caught 2.4 s later at the same height. It rose 7.0 m. Calculate its average speed.', NULL, 2, 'numeric'::answer_type, '5.833', 'm s⁻¹', false, NULL, false, NULL, 'Speed = (7.0 + 7.0) ÷ 2.4 = 5.83 m s⁻¹. Mark scheme (3 marks). C1: distance up and down. C1: ÷ time. A1: speed = 5.83 m s⁻¹.', 3, NULL, NULL),
('68df185f-1b0e-5870-8f8f-7f977a7fed04', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 25, 25, 'A boat moves 1.2 km north in 4.0 minutes and then 0.5 km south in 2.0 minutes. Calculate its average velocity over the 6.0 minutes.', NULL, 2, 'numeric'::answer_type, '1.944', 'm s⁻¹', false, NULL, false, NULL, 'Displacement = 1200 − 500 = 700 m north. v = 700 ÷ 360 = 1.94 m s⁻¹ north. Mark scheme (3 marks). C1: net displacement. C1: ÷ time in s. A1: v = 1.94 m s⁻¹.', 3, NULL, NULL),
('81941c63-b947-5dcc-afeb-1daeb7ec6275', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 26, 26, 'A car travels at 20 m s⁻¹ north for 50 s and then at 10 m s⁻¹ south for 30 s. Calculate its final displacement.', NULL, 2, 'numeric'::answer_type, '700', 'm', false, NULL, false, NULL, 's = 20 × 50 − 10 × 30 = 700 m north. Mark scheme (3 marks). C1: each displacement. C1: subtract. A1: s = 700 m.', 3, NULL, NULL),
('d89d3a34-699d-5d53-a955-c07ea52576d6', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 27, 27, 'A car travels at 20 m s⁻¹ north for 50 s and then at 10 m s⁻¹ south for 30 s. Calculate its average velocity.', NULL, 2, 'numeric'::answer_type, '8.75', 'm s⁻¹', false, NULL, false, NULL, 's = 1000 − 300 = 700 m north; v = 700 ÷ 80 = 8.75 m s⁻¹ north. Mark scheme (4 marks). C1: displacements. C1: net. C1: ÷ total time. A1: v = 8.75 m s⁻¹.', 4, NULL, NULL),
('f94bb7cf-42b7-5dd4-85db-fdbcadbac950', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 28, 28, 'A satellite orbits at constant speed. Which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'Its velocity changes continuously because its direction changes', NULL, false, NULL, false, NULL, 'Uniform circular motion has constant speed but changing velocity. Mark scheme (3 marks). C1: direction changes. C1: velocity changes. A1: D (Its velocity changes continuously because its direction changes).', 3, NULL, NULL),
('eafb4d80-a959-5040-9219-f1de28810277', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 29, 29, 'A runner runs half a lap of a circular track of radius 32 m in 25 s. Calculate her average speed.', NULL, 2, 'numeric'::answer_type, '4.021', 'm s⁻¹', false, NULL, false, NULL, 'd = π × 32 = 100.5 m. Speed = 100.5 ÷ 25 = 4.02 m s⁻¹. Mark scheme (3 marks). C1: half circumference. C1: ÷ time. A1: speed = 4.02 m s⁻¹.', 3, NULL, NULL),
('eecdf1e0-6688-59b7-8c40-4667b7e1da81', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 30, 30, 'A runner runs half a lap of a circular track of radius 32 m in 25 s. Calculate the magnitude of her average velocity.', NULL, 2, 'numeric'::answer_type, '2.56', 'm s⁻¹', false, NULL, false, NULL, 's = 2 × 32 = 64 m; v = 64 ÷ 25 = 2.56 m s⁻¹. Mark scheme (3 marks). C1: diameter. C1: ÷ time. A1: v = 2.56 m s⁻¹.', 3, NULL, NULL),
('39b65f53-4e3b-518e-a30b-de8ccdb179b4', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 31, 31, 'A stone is dropped and falls 20 m. Taking upwards as positive, what is the sign of its velocity and displacement?', NULL, 2, 'multiple_choice'::answer_type, 'Both negative', NULL, false, NULL, false, NULL, 'Both point downwards. Mark scheme (3 marks). C1: downward. C1: negative. A1: B (Both negative).', 3, NULL, NULL),
('70053e61-a1c8-5549-bea9-4bc66ff08eed', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 32, 32, 'A swimmer swims 50 m out along a pool in 40 s and back in 45 s. Calculate her average speed for the two lengths.', NULL, 2, 'numeric'::answer_type, '1.176', 'm s⁻¹', false, NULL, false, NULL, 'Speed = 100 ÷ (40 + 45) = 1.18 m s⁻¹. Mark scheme (3 marks). C1: total distance. C1: total time. A1: speed = 1.18 m s⁻¹.', 3, NULL, NULL),
('2475982f-38de-52ee-aa5d-95c5edb33f74', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 33, 33, 'For the swimmer who swims a length and back, what is her average velocity, and why?', NULL, 2, 'multiple_choice'::answer_type, 'Zero, because she ends where she started', NULL, false, NULL, false, NULL, 'Average velocity = displacement ÷ time. Mark scheme (3 marks). C1: zero displacement. C1: zero velocity. A1: C (Zero, because she ends where she started).', 3, NULL, NULL),
('89cf7975-cecd-597f-b2bf-c32c0d16bf84', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 34, 34, 'A bird flies 300 m north-east in 25 s. Calculate the northward component of its average velocity.', NULL, 2, 'numeric'::answer_type, '8.485', 'm s⁻¹', false, NULL, false, NULL, 'v = 300 ÷ 25 = 12 m s⁻¹; northward component = 12 × cos 45° = 8.49 m s⁻¹. Mark scheme (3 marks). C1: v. C1: component. A1: v_N = 8.49 m s⁻¹.', 3, NULL, NULL),
('cc87746c-f466-5300-90f4-9f0eaab8e3fd', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 35, 35, 'A car averages 25 m s⁻¹ on a 7.5 km road that runs due east. How long does it take?', NULL, 2, 'numeric'::answer_type, '300', 's', false, NULL, false, NULL, 't = 7500 ÷ 25 = 300 s. Mark scheme (3 marks). C1: km to m. C1: t = s/v. A1: t = 300 s.', 3, NULL, NULL),
('7085f871-9bf3-5189-b730-ba3ae5e1002c', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 36, 36, 'A lift goes up 20 m in 10 s, waits 5.0 s and comes down 12 m in 6.0 s. Calculate its average velocity, taking up as positive.', NULL, 2, 'numeric'::answer_type, '0.381', 'm s⁻¹', false, NULL, false, NULL, 'Displacement = 20 − 12 = 8.0 m; v = 8.0 ÷ (10 + 5.0 + 6.0) = 0.381 m s⁻¹. Mark scheme (3 marks). C1: net displacement. C1: total time including the wait. A1: v = 0.381 m s⁻¹.', 3, NULL, NULL),
('0c7a3e7f-cb3c-527a-8cff-86dfeddee6fd', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 37, 37, 'A car''s speedometer shows 60 km h⁻¹ as it rounds a bend. Can its velocity be found from the speedometer alone?', NULL, 2, 'multiple_choice'::answer_type, 'No, the speedometer gives only the speed, not the direction', NULL, false, NULL, false, NULL, 'The direction must also be known. Mark scheme (3 marks). C1: speedometer gives magnitude. C1: direction needed. A1: A (No, the speedometer gives only the speed, not the direction).', 3, NULL, NULL),
('12b381d3-ee78-5b08-978c-9e68176e5034', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 38, 38, 'A boat travels 3.0 km east in 10 minutes, then 4.0 km north in 15 minutes. Calculate the magnitude of its average velocity in km h⁻¹.', NULL, 2, 'numeric'::answer_type, '12', 'km h⁻¹', false, NULL, false, NULL, 's = √(3.0² + 4.0²) = 5.0 km; t = 25 min = 0.4167 h; v = 5.0 ÷ 0.4167 = 12 km h⁻¹. Mark scheme (4 marks). C1: displacement. C1: time in h. C1: v. A1: v = 12 km h⁻¹.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg2e96b4b7-t fg2e96b4b7-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg2e96b4b7-t">Boat route</title><desc id="fg2e96b4b7-d">A boat travels 3.0 km east and then 4.0 km north; the resultant displacement is dashed.</desc><line x1="109.5" y1="234" x2="244.2" y2="234" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="250.5,234 242.3,237.8 242.3,230.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="180" y="248" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">3.0 km</text><line x1="250.5" y1="234" x2="250.5" y2="52.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="250.5,46 254.3,54.2 246.7,54.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="264.5" y="144" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">4.0 km</text><line x1="109.5" y1="234" x2="246.7" y2="51" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="250.5,46 248.6,54.8 242.6,50.2" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="191.2" y="148.4" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="109.5" cy="234" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'A boat travels 3.0 km east and then 4.0 km north; the resultant displacement is dashed.'),
('3103b55d-25f1-563d-878b-464f88cb5b6f', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 39, 39, 'A hare runs 90 m east in 6.0 s and then 30 m west in 4.0 s. Calculate its average velocity.', NULL, 2, 'numeric'::answer_type, '6', 'm s⁻¹', false, NULL, false, NULL, 'Displacement = 90 − 30 = 60 m east; v = 60 ÷ (6.0 + 4.0) = 6.0 m s⁻¹ east. Mark scheme (3 marks). C1: net displacement. C1: total time. A1: v = 6.0 m s⁻¹.', 3, NULL, NULL),
('b539f02a-0910-587e-a6ec-c4301078fe7b', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 40, 40, 'A car is 2.0 km east of a town at 10:00 and 14.0 km east of it at 10:15. Calculate its average velocity in m s⁻¹.', NULL, 2, 'numeric'::answer_type, '13.33', 'm s⁻¹', false, NULL, false, NULL, 'v = (14 000 − 2000) ÷ 900 = 13.3 m s⁻¹ east. Mark scheme (3 marks). C1: displacement. C1: time in s. A1: v = 13.3 m s⁻¹.', 3, NULL, NULL),
('471c0ee4-7ee7-509f-95ed-f88dc6ffa589', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 41, 41, 'A runner completes 1.5 laps of a circular track of radius 40 m in 90 s. (a) Calculate her average speed. (b) Calculate the magnitude of her average velocity.', NULL, 3, 'numeric'::answer_type, '0.8889', 'm s⁻¹', false, NULL, false, NULL, '(a) d = 1.5 × 2π × 40 = 377.0 m; speed = 377.0 ÷ 90 = 4.19 m s⁻¹. (b) She ends opposite the start: s = 80 m; v = 80 ÷ 90 = 0.889 m s⁻¹. Mark scheme (5 marks). C1: distance. C1: speed. M1: displacement = diameter. C1: velocity. A1: v = 0.889 m s⁻¹.', 5, NULL, NULL),
('71121edf-deff-5b57-be26-f25faa99bfb3', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 42, 42, 'A plane flies 400 km north in 50 minutes and then 300 km west in 40 minutes. (a) Calculate the average speed in km h⁻¹. (b) Calculate the magnitude of the average velocity in km h⁻¹. (c) Calculate its direction west of north.', NULL, 3, 'numeric'::answer_type, '36.87', '°', false, NULL, false, NULL, '(a) 700 ÷ 1.5 = 467 km h⁻¹. (b) s = 500 km; v = 500 ÷ 1.5 = 333 km h⁻¹. (c) θ = tan⁻¹(300 ÷ 400) = 36.9°. Mark scheme (6 marks). C1: average speed. C1: displacement. C1: velocity. M1: tan θ. C1: angle. A1: θ = 36.9°.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fge66c5636-t fge66c5636-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fge66c5636-t">Flight north then west</title><desc id="fge66c5636-d">A plane flies 400 km north and then 300 km west; the resultant is dashed with the angle θ west of north marked.</desc><line x1="250.5" y1="234" x2="250.5" y2="52.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="250.5,46 254.3,54.2 246.7,54.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="264.5" y="144" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">400 km</text><line x1="250.5" y1="46" x2="115.8" y2="46" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="109.5,46 117.7,42.2 117.7,49.8" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="180" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">300 km</text><line x1="250.5" y1="234" x2="113.3" y2="51" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="109.5,46 117.4,50.2 111.4,54.8" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="191.2" y="131.6" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="250.5" cy="234" r="3.4" style="fill:currentColor;stroke:none"/><line x1="250.5" y1="234" x2="250.5" y2="190" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:3 3"/><path d="M250.5,204 A30,30 0 0,0 232.5,210" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="237.2" y="194.2" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">θ</text><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'A plane flies 400 km north and then 300 km west; the resultant is dashed with the angle θ west of north marked.'),
('316d054b-104c-593e-89d0-fabc655c172f', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 43, 43, 'A ball is dropped from 5.0 m, bounces and rises to 3.2 m, taking 1.8 s in total. (a) Calculate the distance travelled. (b) Calculate the displacement. (c) Calculate the average velocity, taking down as positive.', NULL, 3, 'numeric'::answer_type, '1', 'm s⁻¹', false, NULL, false, NULL, '(a) 5.0 + 3.2 = 8.2 m. (b) 5.0 − 3.2 = 1.8 m downwards. (c) v = 1.8 ÷ 1.8 = 1.0 m s⁻¹ downwards. Mark scheme (5 marks). C1: distance. C1: displacement. M1: v = s/t. C1: value. A1: v = 1.0 m s⁻¹.', 5, NULL, NULL),
('ffdb4781-7e12-5009-ae4a-e05cdec9ef48', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 44, 44, 'A car drives 12 km north at 60 km h⁻¹ and then 9.0 km east at 45 km h⁻¹. (a) Calculate the time for each stage. (b) Calculate the average speed. (c) Calculate the magnitude of the average velocity, in km h⁻¹.', NULL, 3, 'numeric'::answer_type, '37.5', 'km h⁻¹', false, NULL, false, NULL, '(a) 12 ÷ 60 = 0.20 h; 9.0 ÷ 45 = 0.20 h. (b) 21 ÷ 0.40 = 52.5 km h⁻¹. (c) s = √(12² + 9.0²) = 15 km; v = 15 ÷ 0.40 = 37.5 km h⁻¹. Mark scheme (6 marks). C1: times. C1: average speed. C1: displacement. M1: ÷ total time. C1: value. A1: v = 37.5 km h⁻¹.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg80f8ed9a-t fg80f8ed9a-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg80f8ed9a-t">Car route</title><desc id="fg80f8ed9a-d">A car drives 12 km north and then 9.0 km east; the resultant displacement is dashed.</desc><line x1="109.5" y1="234" x2="109.5" y2="52.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="109.5,46 113.3,54.2 105.7,54.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="95.5" y="144" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">12 km</text><line x1="109.5" y1="46" x2="244.2" y2="46" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="250.5,46 242.3,49.8 242.3,42.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="180" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">9.0 km</text><line x1="109.5" y1="234" x2="246.7" y2="51" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="250.5,46 248.6,54.8 242.6,50.2" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="168.8" y="131.6" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="109.5" cy="234" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'A car drives 12 km north and then 9.0 km east; the resultant displacement is dashed.'),
('8136d12a-07e4-5582-81b8-d99125df4741', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 45, 45, 'A spider crawls round three sides of a square of side 0.60 m in 12 s. (a) Calculate its average speed. (b) Calculate the magnitude of its average velocity. (c) Calculate their ratio, speed ÷ velocity.', NULL, 3, 'numeric'::answer_type, '3', NULL, false, NULL, false, NULL, '(a) 1.8 ÷ 12 = 0.15 m s⁻¹. (b) Displacement = 0.60 m; 0.60 ÷ 12 = 0.050 m s⁻¹. (c) 0.15 ÷ 0.050 = 3.0. Mark scheme (5 marks). C1: speed. C1: displacement. C1: velocity. C1: ratio. A1: ratio = 3.0.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg65c58d2e-t fg65c58d2e-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg65c58d2e-t">Spider path</title><desc id="fg65c58d2e-d">A spider crawls along three sides of a square of side 0.60 m; the displacement from start to finish is dashed.</desc><line x1="86" y1="234" x2="267.7" y2="234" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="274,234 265.8,237.8 265.8,230.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="180" y="248" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">0.60 m</text><line x1="274" y1="234" x2="274" y2="52.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="274,46 277.8,54.2 270.2,54.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="288" y="144" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">0.60 m</text><line x1="274" y1="46" x2="92.3" y2="46" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="86,46 94.2,42.2 94.2,49.8" style="fill:currentColor;stroke:none"/><text x="180" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.60 m</text><line x1="86" y1="234" x2="86" y2="52.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="86,46 89.8,54.2 82.2,54.2" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="100" y="140" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="86" cy="234" r="3.4" style="fill:currentColor;stroke:none"/></svg>', 'A spider crawls along three sides of a square of side 0.60 m; the displacement from start to finish is dashed.'),
('fef2f919-6795-5d4b-9fdb-65a9507d41e6', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 46, 46, 'A train travels at 40 m s⁻¹ east for 3.0 minutes, stops for 1.0 minute, then travels at 30 m s⁻¹ west for 2.0 minutes. (a) Calculate the final displacement. (b) Calculate the average velocity over the 6.0 minutes.', NULL, 3, 'numeric'::answer_type, '10', 'm s⁻¹', false, NULL, false, NULL, '(a) 40 × 180 − 30 × 120 = 3600 m east. (b) v = 3600 ÷ 360 = 10 m s⁻¹ east. Mark scheme (5 marks). C1: east displacement. C1: west displacement. M1: net ÷ total time. C1: value. A1: v = 10 m s⁻¹.', 5, NULL, NULL),
('ae416e00-33dc-5468-8d10-1b43358949eb', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 47, 47, 'An object moves round a circle of radius 2.0 m at a constant speed of 4.0 m s⁻¹. (a) Calculate the time for a quarter turn. (b) Calculate the magnitude of the displacement in that time. (c) Calculate the magnitude of the average velocity.', NULL, 3, 'numeric'::answer_type, '3.601', 'm s⁻¹', false, NULL, false, NULL, '(a) t = (2π × 2.0 ÷ 4) ÷ 4.0 = 0.7854 s. (b) s = √(2.0² + 2.0²) = 2.828 m. (c) v = 2.828 ÷ 0.7854 = 3.60 m s⁻¹. Mark scheme (6 marks). C1: arc length. C1: time. C1: chord. M1: v = s/t. C1: value. A1: v = 3.60 m s⁻¹.', 6, NULL, NULL),
('de153f9b-8f17-56cc-972e-9b6f5d2b8b03', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 48, 48, 'A ferry crosses a 1.2 km wide river, arriving 0.50 km downstream, in 6.0 minutes. (a) Calculate the magnitude of its displacement. (b) Calculate the magnitude of its average velocity.', NULL, 3, 'numeric'::answer_type, '3.611', 'm s⁻¹', false, NULL, false, NULL, '(a) s = √(1.2² + 0.50²) = 1.3 km. (b) v = 1300 ÷ 360 = 3.61 m s⁻¹. Mark scheme (5 marks). C1: Pythagoras. C1: value. M1: ÷ time in s. C1: value. A1: v = 3.61 m s⁻¹.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fgadc156c0-t fgadc156c0-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgadc156c0-t">Ferry crossing</title><desc id="fgadc156c0-d">A ferry crosses a river 1.2 km wide and lands 0.50 km downstream; the components are drawn and the displacement is dashed.</desc><line x1="140.8" y1="234" x2="140.8" y2="52.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="140.8,46 144.6,54.2 137,54.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="126.8" y="144" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">1.2 km across</text><line x1="140.8" y1="46" x2="212.9" y2="46" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="219.2,46 211,49.8 211,42.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="180" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">0.50 km</text><line x1="140.8" y1="234" x2="216.7" y2="51.8" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="219.2,46 219.5,55 212.5,52.1" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="167.1" y="134.6" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="140.8" cy="234" r="3.4" style="fill:currentColor;stroke:none"/></svg>', 'A ferry crosses a river 1.2 km wide and lands 0.50 km downstream; the components are drawn and the displacement is dashed.'),
('e88e6c73-6e64-51f7-8540-830348a062c8', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 49, 49, 'A cyclist rides 6.0 km due east at 24 km h⁻¹ and returns 2.0 km due west at 16 km h⁻¹. (a) Calculate the total time. (b) Calculate the average speed. (c) Calculate the average velocity, in km h⁻¹.', NULL, 3, 'numeric'::answer_type, '10.67', 'km h⁻¹', false, NULL, false, NULL, '(a) 0.25 + 0.125 = 0.375 h. (b) 8.0 ÷ 0.375 = 21.3 km h⁻¹. (c) Displacement 4.0 km east; v = 4.0 ÷ 0.375 = 10.7 km h⁻¹ east. Mark scheme (6 marks). C1: times. C1: average speed. C1: displacement. M1: ÷ time. C1: value. A1: v = 10.7 km h⁻¹.', 6, NULL, NULL),
('412726b8-15f7-5d2f-acfb-305bc710b251', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 50, 50, 'A ball travels at 12 m s⁻¹ towards a wall, rebounds at 9.0 m s⁻¹, and the round trip to the wall 6.0 m away and back to the start takes how long? (a) Calculate the time out. (b) Calculate the time back. (c) Give the total time.', NULL, 3, 'numeric'::answer_type, '1.167', 's', false, NULL, false, NULL, '(a) 6.0 ÷ 12 = 0.50 s. (b) 6.0 ÷ 9.0 = 0.667 s. (c) 0.50 + 0.667 = 1.17 s. Mark scheme (5 marks). C1: out. C1: back. M1: add. C1: value. A1: t = 1.17 s.', 5, NULL, NULL),
('17c195fc-1fa5-5fa3-a632-4872cec9f8b8', '4653a171-76f9-4b44-bc1d-19802787195f', 'd47d25c0-5538-419d-9d8f-026400e11f72', 'a-level', '1.3', '9702 coursebook 1.3 · Speed and velocity', 51, 51, 'A drone flies 600 m north at 12 m s⁻¹ and then 800 m east at 16 m s⁻¹. (a) Calculate the total time. (b) Calculate the magnitude of its average velocity.', NULL, 3, 'numeric'::answer_type, '10', 'm s⁻¹', false, NULL, false, NULL, '(a) t = 600 ÷ 12 + 800 ÷ 16 = 100 s. (b) s = √(600² + 800²) = 1000 m; v = 1000 ÷ 100 = 10 m s⁻¹. Mark scheme (5 marks). C1: times. C1: displacement. M1: ÷ total time. C1: value. A1: v = 10 m s⁻¹.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fgceace679-t fgceace679-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgceace679-t">Drone flight</title><desc id="fgceace679-d">A drone flies 600 m north and then 800 m east; the resultant displacement is dashed.</desc><line x1="60" y1="230" x2="60" y2="56.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="60,50 63.8,58.1 56.2,58.1" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="46" y="144" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">600 m</text><line x1="60" y1="50" x2="293.7" y2="50" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="300,50 291.9,53.8 291.9,46.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="180" y="36" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">800 m</text><line x1="60" y1="230" x2="295" y2="53.8" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="300,50 295.8,57.9 291.2,51.8" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="171.6" y="128.8" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="60" cy="230" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'A drone flies 600 m north and then 800 m east; the resultant displacement is dashed.')
