INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('a1ccaca4-8d15-58c0-8a2f-f0efa191f5f3', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'a-level', '1.4', '9702 coursebook 1.4 · Displacement–time graphs', 1, 1, 'What does the gradient of a displacement–time graph represent?', NULL, 1, 'multiple_choice'::answer_type, 'The velocity', NULL, false, NULL, false, NULL, 'The gradient is Δs/Δt, the rate of change of displacement. Mark scheme (1 mark). B1: C (The velocity).', 1, NULL, NULL),
('5155e69f-3089-5e8a-b098-bdd933047afc', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'a-level', '1.4', '9702 coursebook 1.4 · Displacement–time graphs', 2, 2, 'A displacement–time graph is a horizontal line. What does this show?', NULL, 1, 'multiple_choice'::answer_type, 'The object is at rest', NULL, false, NULL, false, NULL, 'Displacement does not change. Mark scheme (1 mark). B1: A (The object is at rest).', 1, NULL, NULL),
