('9e09f1c1-d251-526c-84ac-7bca095870cf', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'a-level', '1.4', '9702 coursebook 1.4 · Displacement–time graphs', 14, 14, 'A car''s s–t graph rises in a straight line by 150 m in 6.0 s. Calculate its velocity.', NULL, 1, 'numeric'::answer_type, '25', 'm s⁻¹', false, NULL, false, NULL, 'v = 150 ÷ 6.0 = 25 m s⁻¹. Mark scheme (2 marks). C1: gradient. A1: v = 25 m s⁻¹.', 2, NULL, NULL),
('f4c2d324-31dc-5ece-9693-fab7add07d4b', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'a-level', '1.4', '9702 coursebook 1.4 · Displacement–time graphs', 15, 15, 'A displacement–time graph becomes less steep with time. What is happening?', NULL, 1, 'multiple_choice'::answer_type, 'The object is slowing down', NULL, false, NULL, false, NULL, 'A decreasing gradient means a decreasing velocity. Mark scheme (1 mark). B1: C (The object is slowing down).', 1, NULL, NULL),
('66ebc923-273d-5b0b-9312-9cc2090a433c', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'a-level', '1.4', '9702 coursebook 1.4 · Displacement–time graphs', 16, 16, 'A walker''s s–t graph is a straight line through (0 s, 0 m) and (50 s, 70 m). Calculate her velocity.', NULL, 1, 'numeric'::answer_type, '1.4', 'm s⁻¹', false, NULL, false, NULL, 'v = 70 ÷ 50 = 1.4 m s⁻¹. Mark scheme (2 marks). C1: gradient. A1: v = 1.4 m s⁻¹.', 2, NULL, NULL),
('a5b52a01-ca09-5124-b79b-cfc625d49634', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'a-level', '1.4', '9702 coursebook 1.4 · Displacement–time graphs', 17, 17, 'Can a displacement–time graph be a vertical line?', NULL, 1, 'multiple_choice'::answer_type, 'No, it would mean infinite velocity', NULL, false, NULL, false, NULL, 'An object cannot change position in zero time. Mark scheme (1 mark). B1: A (No, it would mean infinite velocity).', 1, NULL, NULL),
('8d5571a3-f102-5c03-bab9-0fb76662e775', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'a-level', '1.4', '9702 coursebook 1.4 · Displacement–time graphs', 18, 18, 'On a straight s–t graph a trolley moves from 0.40 m at 1.0 s to 1.60 m at 4.0 s. Calculate its velocity.', NULL, 1, 'numeric'::answer_type, '0.4', 'm s⁻¹', false, NULL, false, NULL, 'v = (1.60 − 0.40) ÷ (4.0 − 1.0) = 0.40 m s⁻¹. Mark scheme (2 marks). C1: Δs/Δt. A1: v = 0.40 m s⁻¹.', 2, NULL, NULL),
('0fb1de79-4160-5e5f-bfc1-e14a5adab633', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'a-level', '1.4', '9702 coursebook 1.4 · Displacement–time graphs', 19, 19, 'What does the area under a displacement–time graph represent?', NULL, 1, 'multiple_choice'::answer_type, 'It has no useful physical meaning', NULL, false, NULL, false, NULL, 'Velocity comes from the gradient; area is used for v–t graphs. Mark scheme (1 mark). B1: B (It has no useful physical meaning).', 1, NULL, NULL),
