('1c2c015a-5ebb-5c31-88e4-311b32cb1294', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'a-level', '1.4', '9702 coursebook 1.4 · Displacement–time graphs', 24, 24, 'A ball''s s–t graph is a curve that rises, levels off at the top and falls. What happens at the top?', NULL, 2, 'multiple_choice'::answer_type, 'The velocity is momentarily zero', NULL, false, NULL, false, NULL, 'Zero gradient means zero velocity. Mark scheme (3 marks). C1: gradient zero. C1: velocity zero. A1: D (The velocity is momentarily zero).', 3, NULL, NULL),
('ad1597fc-c7a6-5d72-9a5e-6a04db8aa698', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'a-level', '1.4', '9702 coursebook 1.4 · Displacement–time graphs', 25, 25, 'Two runners start together. Runner A''s s–t graph has gradient 6.0 m s⁻¹ and runner B''s 5.0 m s⁻¹. How far ahead is A after 40 s?', NULL, 2, 'numeric'::answer_type, '40', 'm', false, NULL, false, NULL, 'Gap = (6.0 − 5.0) × 40 = 40 m. Mark scheme (3 marks). C1: difference in gradients. C1: × time. A1: Δs = 40 m.', 3, NULL, NULL),
