('94d5cb8b-430d-5865-b66f-b639320caf5c', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'a-level', '1.4', '9702 coursebook 1.4 · Displacement–time graphs', 29, 29, 'A car moving at a steady 15 m s⁻¹ passes a marker at t = 0 at s = 40 m. Calculate its displacement at t = 8.0 s.', NULL, 2, 'numeric'::answer_type, '160', 'm', false, NULL, false, NULL, 's = 40 + 15 × 8.0 = 160 m. Mark scheme (3 marks). C1: s = s₀ + vt. C1: value. A1: s = 160 m.', 3, NULL, NULL),
('7f135492-f4d8-527d-af86-81463476f496', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'a-level', '1.4', '9702 coursebook 1.4 · Displacement–time graphs', 30, 30, 'Two s–t graphs cross at t = 6.0 s. What does this show?', NULL, 2, 'multiple_choice'::answer_type, 'The two objects are at the same position at 6.0 s', NULL, false, NULL, false, NULL, 'Equal s at the same t means the same place. Mark scheme (3 marks). C1: same displacement. C1: not same velocity. A1: C (The two objects are at the same position at 6.0 s).', 3, NULL, NULL),
('d2b6a9fe-c5a7-5f7b-ad6c-c2bbdd5ef754', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'a-level', '1.4', '9702 coursebook 1.4 · Displacement–time graphs', 31, 31, 'A runner at constant speed passes 120 m at 20 s and 210 m at 35 s. Calculate her velocity.', NULL, 2, 'numeric'::answer_type, '6', 'm s⁻¹', false, NULL, false, NULL, 'v = (210 − 120) ÷ (35 − 20) = 6.0 m s⁻¹. Mark scheme (3 marks). C1: Δs. C1: Δt. A1: v = 6.0 m s⁻¹.', 3, NULL, NULL),
