('147da97f-fb5e-5cd8-a51f-8d79188018c4', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'a-level', '1.4', '9702 coursebook 1.4 · Displacement–time graphs', 37, 37, 'Why can an s–t graph show the direction of motion but a distance–time graph cannot?', NULL, 2, 'multiple_choice'::answer_type, 'Displacement can be negative or decrease, but distance only increases', NULL, false, NULL, false, NULL, 'Distance never decreases. Mark scheme (3 marks). C1: displacement signed. C1: distance never decreases. A1: D (Displacement can be negative or decrease, but distance only increases).', 3, NULL, NULL),
('049009a5-b777-5e86-acbe-8c8fa7911947', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'a-level', '1.4', '9702 coursebook 1.4 · Displacement–time graphs', 38, 38, 'A train''s s–t graph shows 1.2 km at 2.0 min and 4.8 km at 5.0 min, in a straight line. Calculate its velocity in m s⁻¹.', NULL, 2, 'numeric'::answer_type, '20', 'm s⁻¹', false, NULL, false, NULL, 'v = (4800 − 1200) ÷ ((5.0 − 2.0) × 60) = 20 m s⁻¹. Mark scheme (3 marks). C1: units. C1: gradient. A1: v = 20 m s⁻¹.', 3, NULL, NULL),
('75d7f269-982c-5e7e-b4c6-95aad420b6da', '157573de-e4fd-418b-9e2b-b4772e5fe137', 'b2e3d430-7699-4dac-9f55-e84c5cd5ce9b', 'a-level', '1.4', '9702 coursebook 1.4 · Displacement–time graphs', 39, 39, 'A car''s s–t graph rises in straight lines from 0 to 300 m in the first 20 s and from 300 m to 700 m in the next 40 s. Calculate its average velocity over the 60 s.', NULL, 2, 'numeric'::answer_type, '11.67', 'm s⁻¹', false, NULL, false, NULL, 'v = 700 ÷ 60 = 11.7 m s⁻¹. Mark scheme (3 marks). C1: total displacement. C1: total time. A1: v = 11.7 m s⁻¹.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg4b332216-t fg4b332216-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg4b332216-t">Two-stage journey</title><desc id="fg4b332216-d">An s–t graph rising in straight lines from 0 to 300 m in 20 s and from 300 m to 700 m in the next 40 s.</desc><line x1="36.2" y1="34" x2="36.2" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="93.8" y1="34" x2="93.8" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="151.4" y1="34" x2="151.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="209.1" y1="34" x2="209.1" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="266.7" y1="34" x2="266.7" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="324.4" y1="34" x2="324.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);str